    ('c0976254-746a-5ecc-adb5-51c29ecaf4fc'::uuid, 'Quiz — Marx, Weber, Bourdieu : trois façons de découper', 'SES', 'Tle', 'Les théories des classes sociales', 'b019679d-f62c-5288-8285-706d77be9cbb'::uuid),
    ('faed763c-242c-5c5e-8de3-cc54edc345b2'::uuid, 'Quiz — Beaucoup plus d’élèves, pas les mêmes places', 'SES', 'Tle', 'La massification scolaire depuis les années 1950', 'bc325d88-2595-5a3d-98b5-73b97b8d800a'::uuid),
    ('df2afc58-82f4-5b4b-83fb-be625e2641b5'::uuid, 'Quiz — Pourquoi l’École reproduit ce qu’elle prétend corriger', 'SES', 'Tle', 'Une inégalité des chances persistante', '53885106-4391-59eb-a7eb-ee15e0fd447a'::uuid),
    ('890143ce-a512-5566-8026-a56344e262b7'::uuid, 'Quiz — Lire une table de mobilité sans se tromper de ligne', 'SES', 'Tle', 'Qu’est-ce que la mobilité sociale ?', '8eaaff55-dd43-52f5-b487-3aea55f71fd0'::uuid),
    ('9b773f94-2fff-52fe-b8cd-a8f35c1c5cea'::uuid, 'Quiz — Beaucoup de mouvement, peu de fluidité', 'SES', 'Tle', 'L’évolution de la mobilité sociale', '7a2e0577-063a-5022-915e-d1d87ef44196'::uuid),
    ('d27568ad-2911-5978-a01a-4c5067427eb2'::uuid, 'Quiz — La norme et ses marges', 'SES', 'Tle', 'L’évolution des formes de l’emploi', '8c5f8c74-2939-5795-b0ff-d1b9fb675f75'::uuid),
    ('56f8f880-03f4-543c-b7aa-f28e9f02203f'::uuid, 'Quiz — De la chaîne au tableau de bord', 'SES', 'Tle', 'L’organisation du travail : quels modèles ?', '2e835744-f8ff-5dee-bae0-1c80753db934'::uuid),
    ('de39fca5-e4d9-5052-9b4a-2a0274b24612'::uuid, 'Quiz — Le travail intègre-t-il encore ?', 'SES', 'Tle', 'L’évolution du lien social dans le monde du travail', 'f85d8578-6ec6-5803-a7c3-822f4bf233db'::uuid),
    ('761c6b6a-ae81-5ca9-93db-df0d3cdab07d'::uuid, 'Quiz — Pourquoi s’engager quand on pourrait ne rien faire', 'SES', 'Tle', 'Diverses formes d’engagement citoyen', '0d117c25-3c75-5489-b56b-3abc49992b42'::uuid),
    ('034bb51a-ba12-5e7e-809c-785bd692f575'::uuid, 'Quiz — Des conflits du travail aux mouvements de société', 'SES', 'Tle', 'L’évolution des formes de l’action collective', '889304af-bb80-5e6e-9fa7-6d6728671397'::uuid),
    ('f2d37f99-f4c3-5a26-b9e6-05ca62d58216'::uuid, 'Quiz — Une différence n’est pas une inégalité', 'SES', 'Tle', 'Des inégalités multiformes et cumulatives', '9bfc59a4-a168-5fee-8f92-c694f683323c'::uuid),
    ('13b1fc4c-e8a8-5533-bf59-5f566faaff93'::uuid, 'Quiz — Trois outils, trois questions différentes', 'SES', 'Tle', 'La mesure des inégalités économiques : une diversité d’outils', 'b52e796c-ac73-51ad-a8f0-79493ebaa0e2'::uuid),
    ('3acce5bf-f3da-5961-bdf9-ff62c1f3526b'::uuid, 'Quiz — Quelle égalité vise-t-on, au juste ?', 'SES', 'Tle', 'Pouvoirs publics et justice sociale', 'f352d8f2-879b-5c3a-8dc7-063a521e5712'::uuid),
    ('d2f4114d-5c5d-50d8-9d0d-38a02f2c6083'::uuid, 'Quiz — Un bien commun que personne ne possède', 'SES', 'Tle', 'Coopération et conflit dans la conduite de l’action publique pour l’environnement', '6bf1257d-92da-58d0-a1b6-d1d4f7a88b01'::uuid),
    ('dfc037f8-500c-5392-9c6d-2665c0f4eef6'::uuid, 'Quiz — Interdire, taxer, ou faire payer le droit de polluer', 'SES', 'Tle', 'Les principaux instruments des politiques climatiques', '9422db3c-4b00-54fb-8aef-1b3fe306e280'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('bb94b20d-9f62-56ef-ae3c-4a7bb4a121d7'::uuid, '7fd565cd-58ec-5488-a40e-fcfef411ef2b'::uuid, 'Qu’est-ce que la croissance intensive ?', 'mcq', '["Produire plus avec la même quantité de facteurs, grâce aux gains de productivité","Produire plus en utilisant plus de travail et de capital","Produire plus en augmentant les prix","Produire plus en réduisant les importations"]'::jsonb, 0, 'C’est la seule soutenable à long terme : les facteurs ne peuvent pas croître indéfiniment.', 1),
    ('e5d42ec1-c97f-5b27-90f4-ce1272ecf037'::uuid, '7fd565cd-58ec-5488-a40e-fcfef411ef2b'::uuid, 'Que mesure la productivité globale des facteurs (PGF) ?', 'mcq', '["La part de la croissance inexpliquée par la hausse du travail et du capital","La production par salarié","Le stock de capital fixe","Le taux d’investissement"]'::jsonb, 0, 'Elle sert d’approximation du progrès technique.', 2),
    ('9a8bb05a-632b-556e-befd-05f023c6f20f'::uuid, '7fd565cd-58ec-5488-a40e-fcfef411ef2b'::uuid, 'Qu’appelle-t-on capital humain ?', 'mcq', '["L’ensemble des savoirs et compétences incorporés dans les travailleurs","Le nombre d’actifs occupés","Les machines utilisées par les salariés","La masse salariale d’une entreprise"]'::jsonb, 0, 'Formation, expérience et santé en font partie.', 3),
    ('403f9427-61e0-5414-be3b-b7c21afb3923'::uuid, '7fd565cd-58ec-5488-a40e-fcfef411ef2b'::uuid, 'La destruction créatrice est un concept de Schumpeter.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’innovation détruit des activités anciennes en même temps qu’elle en crée de nouvelles.', 4),
    ('8f6c3894-9be5-5d43-a10c-49887a98a7e4'::uuid, '7fd565cd-58ec-5488-a40e-fcfef411ef2b'::uuid, 'Que disent les théories de la croissance endogène ?', 'mcq', '["Le progrès technique est produit par les décisions d’investissement des agents","La croissance dépend uniquement de la démographie","Le progrès technique est un facteur exogène","La croissance est impossible sans commerce international"]'::jsonb, 0, 'Capital physique, humain, public et technologique en sont les quatre sources.', 5),
    ('b9caa69e-9311-5b73-bdb5-3205ba4d9914'::uuid, '7fd565cd-58ec-5488-a40e-fcfef411ef2b'::uuid, 'Pourquoi l’investissement privé en recherche est-il spontanément insuffisant ?', 'mcq', '["Parce que la connaissance produit des externalités positives dont d’autres profitent","Parce que la recherche est toujours déficitaire","Parce que les entreprises manquent de capital","Parce que l’État l’interdit"]'::jsonb, 0, 'D’où les subventions, le crédit d’impôt recherche et la recherche publique.', 6),
    ('681337a8-afc0-5174-84ce-cee88327d9d5'::uuid, '7fd565cd-58ec-5488-a40e-fcfef411ef2b'::uuid, 'Le PIB mesure le niveau de bien-être d’une population.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il mesure une production. L’IDH y ajoute l’espérance de vie et l’éducation, sans mesurer les inégalités.', 7),
    ('d6231c1a-9b72-50e9-a0b5-160ce32108c5'::uuid, '7fd565cd-58ec-5488-a40e-fcfef411ef2b'::uuid, 'La croissance économique se mesure par la variation…', 'mcq', '["Du PIB en volume","Du PIB en valeur","Du revenu médian","De la population active"]'::jsonb, 0, 'En volume, c’est-à-dire corrigée de l’inflation.', 8),
    ('195471e9-23cc-5292-bb3b-a2d2f9665538'::uuid, '06bf2a13-a0f2-5a2c-9f07-7fde17a72405'::uuid, 'Qu’est-ce qu’une institution, en économie ?', 'mcq', '["L’ensemble des règles du jeu qui fixent les incitations des agents","Un organisme public","Une entreprise publique","Une association reconnue d’utilité publique"]'::jsonb, 0, 'Lois, contrats, droits de propriété, mais aussi normes et habitudes.', 1),
    ('31a61d32-045f-5253-aa0b-f000db0403c0'::uuid, '06bf2a13-a0f2-5a2c-9f07-7fde17a72405'::uuid, 'Que garantit un brevet à son détenteur ?', 'mcq', '["Un monopole temporaire, en échange de la publication de l’invention","Un monopole définitif","Une subvention publique","Une exonération d’impôt"]'::jsonb, 0, 'C’est un compromis entre inciter à innover et diffuser la connaissance.', 2),
    ('3e4b0d50-18be-5516-84bb-7d9cd77fef32'::uuid, '06bf2a13-a0f2-5a2c-9f07-7fde17a72405'::uuid, 'Selon Acemoglu et Robinson, des institutions extractives…', 'mcq', '["Bloquent l’innovation en protégeant les rentes en place","Favorisent la destruction créatrice","Répartissent largement le pouvoir","Sont typiques des pays développés"]'::jsonb, 0, 'Les institutions inclusives, elles, sécurisent les droits du plus grand nombre.', 3),
    ('7618dc9d-0e31-5fa2-9ac4-7a5fa68f06f1'::uuid, '06bf2a13-a0f2-5a2c-9f07-7fde17a72405'::uuid, 'Un brevet trop large peut freiner l’innovation.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Toute innovation s’appuie sur les précédentes : un brevet trop protecteur bloque la suite.', 4),
    ('e5e18db4-7202-5f27-b755-d171409d3909'::uuid, '06bf2a13-a0f2-5a2c-9f07-7fde17a72405'::uuid, 'Pourquoi l’État finance-t-il la recherche fondamentale ?', 'mcq', '["Parce qu’elle n’est pas rentable à court terme pour un acteur privé","Parce que les entreprises n’ont pas de chercheurs","Parce que la loi le lui impose","Parce qu’elle rapporte des brevets rentables"]'::jsonb, 0, 'Ses retombées sont diffuses, lointaines et largement appropriables par d’autres.', 5),
    ('dc871678-c99e-5643-adc4-c8527015fa0e'::uuid, '06bf2a13-a0f2-5a2c-9f07-7fde17a72405'::uuid, 'L’innovation peut être organisationnelle et non technologique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le taylorisme et le toyotisme en sont deux exemples majeurs.', 6),
    ('737f99cd-eef0-5941-80bd-c5e2ce5710c0'::uuid, '06bf2a13-a0f2-5a2c-9f07-7fde17a72405'::uuid, 'Quel est l’effet des droits de propriété sur l’investissement de long terme ?', 'mcq', '["Ils le sécurisent en garantissant l’appropriation du fruit de l’effort","Ils le découragent en taxant les profits","Ils sont sans effet","Ils le remplacent par de l’investissement public"]'::jsonb, 0, 'C’est l’institution la plus déterminante pour l’innovation.', 7),
    ('cfa97ff1-695f-5eba-ba52-155e73041cd4'::uuid, '06bf2a13-a0f2-5a2c-9f07-7fde17a72405'::uuid, 'Selon Schumpeter, l’entrepreneur innovant est nécessairement l’inventeur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est celui qui met l’innovation sur le marché, ce qui est un autre métier.', 8),
    ('405c7456-338c-5de5-9986-f51684a1a454'::uuid, '723d03f0-fea0-5bb9-9d64-93a0f0de3c2e'::uuid, 'Qu’est-ce qu’une externalité négative ?', 'mcq', '["Un effet néfaste subi par un tiers sans compensation par le marché","Une perte comptable pour l’entreprise","Un impôt sur les bénéfices","Une baisse de la demande"]'::jsonb, 0, 'La pollution en est l’exemple type : le pollueur n’en supporte pas le coût.', 1),
    ('c4fa904f-7c72-5acf-9370-2613fa3a6636'::uuid, '723d03f0-fea0-5bb9-9d64-93a0f0de3c2e'::uuid, 'Que défend la soutenabilité forte ?', 'mcq', '["Certains éléments du capital naturel sont irremplaçables et doivent être préservés","Le progrès technique peut compenser toute perte de capital naturel","La croissance doit être maximale","Le capital naturel n’existe pas"]'::jsonb, 0, 'La soutenabilité faible, elle, mise sur la substituabilité des capitaux.', 2),
    ('24bfc2b2-9cb6-500b-8ec3-c1f98207d05e'::uuid, '723d03f0-fea0-5bb9-9d64-93a0f0de3c2e'::uuid, 'Qu’est-ce qu’un découplage absolu ?', 'mcq', '["Les émissions baissent alors que le PIB augmente","Les émissions croissent moins vite que le PIB","Le PIB baisse et les émissions aussi","Il n’y a plus aucune émission"]'::jsonb, 0, 'Le découplage relatif se contente d’un ralentissement des émissions.', 3),
    ('12e7a2ce-8c72-5b8e-8d8f-485490dee682'::uuid, '723d03f0-fea0-5bb9-9d64-93a0f0de3c2e'::uuid, 'L’empreinte carbone d’un pays compte les émissions liées à ses importations.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est pourquoi elle recule bien plus lentement que les émissions territoriales.', 4),
    ('1f95a2b2-f985-53b3-892d-b780ca0b14a4'::uuid, '723d03f0-fea0-5bb9-9d64-93a0f0de3c2e'::uuid, 'Quels sont les quatre types de capital au programme ?', 'mcq', '["Physique, humain, social et naturel","Fixe, circulant, financier et humain","Public, privé, national et étranger","Productif, spéculatif, immobilier et naturel"]'::jsonb, 0, 'Le capital social désigne la qualité des relations et de la confiance.', 5),
    ('735e5410-22de-5064-9aca-396a857f5617'::uuid, '723d03f0-fea0-5bb9-9d64-93a0f0de3c2e'::uuid, 'Le rapport Brundtland (1987) a défini le développement durable.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '« Répondre aux besoins du présent sans compromettre ceux des générations futures ».', 6),
    ('f35691c2-c022-557e-a1bd-b5308951cb9d'::uuid, '723d03f0-fea0-5bb9-9d64-93a0f0de3c2e'::uuid, 'Pourquoi le PIB est-il une mauvaise boussole environnementale ?', 'mcq', '["Il ignore la destruction du capital naturel et compte le nettoyage comme une production","Il ne mesure que les services","Il est calculé tous les dix ans","Il exclut l’industrie"]'::jsonb, 0, 'Une marée noire augmente le PIB : c’est la critique la plus solide de son usage.', 7),
    ('8e7197db-4ad0-5037-83ba-f19c645a3f8f'::uuid, '723d03f0-fea0-5bb9-9d64-93a0f0de3c2e'::uuid, 'Le programme de Terminale tranche entre croissance verte et décroissance.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il demande de connaître les arguments et les données des deux positions.', 8),
    ('2f631bed-d4da-5072-ab08-e611cc60f812'::uuid, '3c4d6fe8-1fd5-5f77-9ec2-633e87281d79'::uuid, 'Sur quoi repose l’avantage comparatif de Ricardo ?', 'mcq', '["Le coût d’opportunité : se spécialiser là où le désavantage est le plus faible","La productivité absolue la plus élevée","La dotation en capital","Le niveau des salaires"]'::jsonb, 0, 'Même un pays moins productif en tout gagne à l’échange.', 1),
    ('6c300466-5edb-511c-b2d8-05449e9e9137'::uuid, '3c4d6fe8-1fd5-5f77-9ec2-633e87281d79'::uuid, 'Que dit le modèle HOS ?', 'mcq', '["La spécialisation dépend de la dotation relative en facteurs de production","Le commerce dépend des seuls coûts salariaux","Les pays doivent produire tous les biens","Le libre-échange nuit toujours aux pays pauvres"]'::jsonb, 0, 'Heckscher-Ohlin-Samuelson : un pays exporte ce qui utilise intensément son facteur abondant.', 2),
    ('f0a4a1f7-51c0-526f-89d8-39fa146470a0'::uuid, '3c4d6fe8-1fd5-5f77-9ec2-633e87281d79'::uuid, 'Qu’est-ce que le commerce intrabranche ?', 'mcq', '["L’échange de produits d’une même branche entre pays","L’échange entre entreprises d’un même pays","L’échange de matières premières contre des produits finis","Le commerce à l’intérieur d’une entreprise"]'::jsonb, 0, 'Des voitures contre des voitures : c’est l’essentiel du commerce entre pays développés.', 3),
    ('13750cff-2c8f-5fe3-920b-ba7f2b65ca5e'::uuid, '3c4d6fe8-1fd5-5f77-9ec2-633e87281d79'::uuid, 'Quelle explication rend compte du commerce intrabranche ?', 'mcq', '["La différenciation des produits et les économies d’échelle","L’avantage absolu de Smith","La dotation en ressources naturelles","Le protectionnisme"]'::jsonb, 0, 'S’y ajoute la fragmentation de la chaîne de valeur.', 4),
    ('4cb6a7ba-de58-516f-8931-f8b9cf69ae19'::uuid, '3c4d6fe8-1fd5-5f77-9ec2-633e87281d79'::uuid, 'Les avantages comparatifs d’un pays sont donnés une fois pour toutes.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils se construisent : la Corée du Sud n’en avait aucun dans l’électronique en 1960.', 5),
    ('1c4e203d-6e5f-50ef-b7f4-755fe838fcdb'::uuid, '3c4d6fe8-1fd5-5f77-9ec2-633e87281d79'::uuid, 'Qu’appelle-t-on protectionnisme éducateur ?', 'mcq', '["Une protection temporaire d’une industrie naissante, défendue par List","Une taxe sur les produits éducatifs","Une interdiction totale des importations","Un quota d’importation permanent"]'::jsonb, 0, 'Elle vise à laisser une industrie atteindre sa taille critique avant l’ouverture.', 6),
    ('8f0beddb-2a2f-546c-b42b-fa3e0b0be738'::uuid, '3c4d6fe8-1fd5-5f77-9ec2-633e87281d79'::uuid, 'Les économies d’échelle abaissent le coût unitaire quand la production augmente.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est ce qui pousse chaque pays à se spécialiser sur un segment de la branche.', 7),
    ('099567d7-0a76-5142-a3d1-a72c51dabf11'::uuid, '3c4d6fe8-1fd5-5f77-9ec2-633e87281d79'::uuid, 'Le raisonnement de Smith sur l’avantage absolu échoue quand…', 'mcq', '["Un pays est plus productif que l’autre dans toutes les productions","Les deux pays ont la même productivité","Les coûts de transport sont nuls","Les produits sont différenciés"]'::jsonb, 0, 'C’est exactement le cas que Ricardo résout avec l’avantage comparatif.', 8),
    ('692be280-8e22-5195-abab-ff90d06755d3'::uuid, 'd5632710-2307-50b8-83cd-d154c3a1bb2f'::uuid, 'Pourquoi le protectionnisme est-il politiquement puissant ?', 'mcq', '["Les pertes sont concentrées et visibles, les gains diffus et invisibles","Parce qu’il enrichit toujours le pays","Parce que l’OMC l’encourage","Parce que les consommateurs le réclament"]'::jsonb, 0, 'Les perdants savent qui ils sont, les gagnants l’ignorent.', 1),
    ('601b20af-674b-5402-ac81-82e830b2e29e'::uuid, 'd5632710-2307-50b8-83cd-d154c3a1bb2f'::uuid, 'Quel est le principal gain du libre-échange pour le consommateur ?', 'mcq', '["Des prix plus bas et une plus grande variété de produits","Un emploi mieux protégé","Un salaire plus élevé","Une monnaie plus forte"]'::jsonb, 0, 'La mise en concurrence des producteurs fait baisser les prix.', 2),
    ('dc0bb4f9-87d4-5e0c-aa28-7061ca9492c0'::uuid, 'd5632710-2307-50b8-83cd-d154c3a1bb2f'::uuid, 'Qu’est-ce qu’une barrière non tarifaire ?', 'mcq', '["Un quota, une norme technique ou une subvention","Un droit de douane","Un taux de change fixe","Une taxe sur les exportations"]'::jsonb, 0, 'Ce sont les plus utilisées aujourd’hui, les tarifs étant encadrés par l’OMC.', 3),
    ('07a716dd-c653-553e-8491-4994774e5a13'::uuid, 'd5632710-2307-50b8-83cd-d154c3a1bb2f'::uuid, 'Selon le modèle HOS, l’ouverture d’un pays développé pèse sur…', 'mcq', '["Le travail peu qualifié","Le travail qualifié","Le capital","Les revenus fonciers"]'::jsonb, 0, 'C’est le facteur relativement rare dans un pays développé.', 4),
    ('faa22127-7637-5f3f-a92a-0f9be41468a1'::uuid, 'd5632710-2307-50b8-83cd-d154c3a1bb2f'::uuid, 'L’OMC a succédé au GATT en 1995.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle y ajoute un organe de règlement des différends.', 5),
    ('5d539b30-e247-53bd-a2d1-73b7db190b8b'::uuid, 'd5632710-2307-50b8-83cd-d154c3a1bb2f'::uuid, 'En quoi consiste la « flexicurité » ?', 'mcq', '["Accompagner les transitions par la formation et l’indemnisation plutôt que protéger les emplois","Interdire les licenciements","Fixer les prix des importations","Subventionner les exportations"]'::jsonb, 0, 'C’est le modèle danois, une alternative au protectionnisme.', 6),
    ('8d91d23f-af93-5d34-a252-e7925d80161b'::uuid, 'd5632710-2307-50b8-83cd-d154c3a1bb2f'::uuid, 'Le protectionnisme n’a que des effets positifs pour le pays qui l’applique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il renchérit les intrants, invite aux représailles et retarde l’adaptation.', 7),
    ('a1c1a58e-8785-5e03-9b29-26ab81edb080'::uuid, 'd5632710-2307-50b8-83cd-d154c3a1bb2f'::uuid, 'Depuis les années 2010, le commerce mondial est marqué par…', 'mcq', '["Un essoufflement du multilatéralisme au profit d’accords régionaux","La disparition de l’OMC","La fin des barrières non tarifaires","Un libre-échange total"]'::jsonb, 0, 'S’y ajoute un retour des mesures unilatérales.', 8),
    ('12251bcf-9778-502e-a253-36a5dbe49218'::uuid, '0723e43a-e899-5e38-a2f9-9e8fb14c3d40'::uuid, 'Qu’est-ce qu’un investissement direct à l’étranger (IDE) ?', 'mcq', '["Une prise de contrôle durable d’une entreprise étrangère ou la création d’une filiale","L’achat d’actions à but spéculatif","Une exportation de biens","Un prêt à un État étranger"]'::jsonb, 0, 'Il se distingue de l’investissement de portefeuille par la durée et le contrôle.', 1),
    ('ffbef2ca-2b07-55d5-a938-2e401a419ebb'::uuid, '0723e43a-e899-5e38-a2f9-9e8fb14c3d40'::uuid, 'Quel est le motif majoritaire des IDE ?', 'mcq', '["Conquérir un marché","Réduire le coût du travail","Échapper à l’impôt","Accéder à des matières premières"]'::jsonb, 0, 'La délocalisation au sens strict ne représente qu’une partie des IDE.', 2),
    ('93c9d127-b33c-50cd-bbd5-b34c6d2c4823'::uuid, '0723e43a-e899-5e38-a2f9-9e8fb14c3d40'::uuid, 'Que décrit la « courbe du sourire » ?', 'mcq', '["La valeur ajoutée se concentre à la conception et à la commercialisation, pas à l’assemblage","La hausse des profits avec la taille de la firme","La relation entre salaire et productivité","L’évolution du commerce mondial"]'::jsonb, 0, 'D’où l’intérêt, pour un pays, de tenir les deux extrémités de la chaîne.', 3),
    ('a93af1ba-8930-586f-aa85-900bb0f7afa3'::uuid, '0723e43a-e899-5e38-a2f9-9e8fb14c3d40'::uuid, 'Environ un tiers du commerce mondial est du commerce intra-firme.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il s’agit d’échanges entre unités d’une même multinationale.', 4),
    ('cf3af652-8248-52df-9768-05e9c9f7a0d1'::uuid, '0723e43a-e899-5e38-a2f9-9e8fb14c3d40'::uuid, 'Pourquoi les statistiques douanières surestiment-elles le poids des pays assembleurs ?', 'mcq', '["Elles comptent la valeur totale du bien à chaque passage de frontière","Elles excluent les services","Elles sont calculées en monnaie locale","Elles ignorent les réexportations"]'::jsonb, 0, 'D’où les mesures alternatives du commerce en valeur ajoutée.', 5),
    ('fd86f662-5d9e-51c0-8506-b71e8fa0ea67'::uuid, '0723e43a-e899-5e38-a2f9-9e8fb14c3d40'::uuid, 'Externaliser suppose de posséder l’unité de production.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La firme garde le contrôle par le contrat et la marque, sans porter l’investissement.', 6),
    ('4f4355e3-2778-5d35-b30e-bee2faf4fe37'::uuid, '0723e43a-e899-5e38-a2f9-9e8fb14c3d40'::uuid, 'Quel accord international vise la concurrence fiscale entre pays d’accueil ?', 'mcq', '["L’accord OCDE sur un taux minimal d’imposition de 15 %","Les accords de Bretton Woods","Le protocole de Kyoto","Le traité de Maastricht"]'::jsonb, 0, 'Il répond à la localisation des profits dans les pays à faible imposition.', 7),
    ('12408749-7688-5e68-82d8-bf5e7ae84b08'::uuid, '0723e43a-e899-5e38-a2f9-9e8fb14c3d40'::uuid, 'La désindustrialisation des pays développés s’explique uniquement par les délocalisations.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les gains de productivité industrielle y contribuent au moins autant.', 8),
    ('52b5b57c-288c-5f26-993d-adf552caf438'::uuid, 'eb97db57-5a58-5dd0-ba76-cf71ab09051c'::uuid, 'Quelles sont les trois conditions du chômage au sens du BIT ?', 'mcq', '["Être sans emploi, disponible et en recherche active","Être inscrit à France Travail, indemnisé et disponible","Être sans emploi depuis plus de trois mois","Avoir moins de 25 ans et être sans diplôme"]'::jsonb, 0, 'Les trois doivent être remplies simultanément.', 1),
    ('9a2ac493-c9e0-59ee-80c5-a2e28bc472b0'::uuid, 'eb97db57-5a58-5dd0-ba76-cf71ab09051c'::uuid, 'À quoi rapporte-t-on le nombre de chômeurs pour calculer le taux de chômage ?', 'mcq', '["À la population active","À la population totale","À la population en âge de travailler","Aux actifs occupés seulement"]'::jsonb, 0, 'Population active = actifs occupés + chômeurs.', 2),
    ('6c17b0fd-2776-5ac0-9a5e-aba5d7f06e0c'::uuid, 'eb97db57-5a58-5dd0-ba76-cf71ab09051c'::uuid, 'Qu’est-ce que le halo autour du chômage ?', 'mcq', '["Les personnes qui souhaitent travailler sans remplir les trois critères du BIT","Les chômeurs de longue durée","Les chômeurs indemnisés","Les personnes en formation"]'::jsonb, 0, 'Plus de deux millions de personnes en France, invisibles dans le taux officiel.', 3),
    ('bef32f35-5af5-501f-94fb-a971398c4071'::uuid, 'eb97db57-5a58-5dd0-ba76-cf71ab09051c'::uuid, 'Un inscrit à France Travail est nécessairement un chômeur au sens du BIT.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les catégories B et C travaillent à temps partiel ; certains ne recherchent pas activement.', 4),
    ('4fd39058-b129-519a-a4bc-f717dc72164e'::uuid, 'eb97db57-5a58-5dd0-ba76-cf71ab09051c'::uuid, 'Qu’est-ce que le taux d’emploi ?', 'mcq', '["La part des actifs occupés dans la population en âge de travailler","La part des chômeurs dans la population active","Le nombre d’emplois créés dans l’année","La part des CDI dans l’emploi total"]'::jsonb, 0, 'Deux pays peuvent avoir le même taux de chômage et des taux d’emploi très différents.', 5),
    ('3aed1363-7fb4-5461-87cb-76bbc88e4e4c'::uuid, 'eb97db57-5a58-5dd0-ba76-cf71ab09051c'::uuid, 'Une personne en temps partiel subi est comptée comme chômeuse.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est active occupée, mais en situation de sous-emploi.', 6),
    ('878c118a-0810-51bb-b7cb-13e39aec09a0'::uuid, 'eb97db57-5a58-5dd0-ba76-cf71ab09051c'::uuid, 'Quelle enquête permet à l’INSEE de mesurer le chômage au sens du BIT ?', 'mcq', '["L’enquête Emploi, menée auprès d’un échantillon de ménages","Le recensement décennal","Les fichiers de France Travail","La déclaration sociale nominative"]'::jsonb, 0, 'C’est la seule mesure comparable au niveau international.', 7),
    ('c3735c8d-61f0-550b-b270-413572618101'::uuid, 'eb97db57-5a58-5dd0-ba76-cf71ab09051c'::uuid, 'Une baisse du taux de chômage peut traduire un découragement des chômeurs.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ils sortent alors de la population active : seul le taux d’emploi permet de trancher.', 8),
    ('5aadb37f-4f36-5f5f-96d5-f859ce03ae8f'::uuid, 'e27d6632-816a-565b-95af-d437eb4beb75'::uuid, 'Le chômage keynésien est un chômage…', 'mcq', '["Par insuffisance de la demande anticipée","Par excès de salaire réel","Par inadéquation des qualifications","Volontaire"]'::jsonb, 0, 'Il est involontaire : les chômeurs accepteraient le salaire en vigueur.', 1),
    ('45428763-7400-5648-bf9c-b41e57b25e6d'::uuid, 'e27d6632-816a-565b-95af-d437eb4beb75'::uuid, 'Qu’est-ce que le coin fiscalo-social ?', 'mcq', '["L’écart entre le coût du travail pour l’employeur et le salaire net perçu","La part de l’impôt dans le PIB","Le taux du salaire minimum","La différence entre salaire brut et salaire médian"]'::jsonb, 0, 'Il est constitué des cotisations sociales et des prélèvements sur le travail.', 2),
    ('7ad0c440-5109-58d6-991b-d902245641ad'::uuid, 'e27d6632-816a-565b-95af-d437eb4beb75'::uuid, 'Que dit la théorie du salaire d’efficience ?', 'mcq', '["L’employeur paie volontairement au-dessus du marché pour attirer et motiver","Le salaire minimum doit être supprimé","Les salaires doivent suivre l’inflation","Le salaire est fixé par l’État"]'::jsonb, 0, 'Le chômage devient durable sans rigidité imposée de l’extérieur.', 3),
    ('62cf80b0-b98f-5d69-8581-ae2dfa4fda03'::uuid, 'e27d6632-816a-565b-95af-d437eb4beb75'::uuid, 'Qu’est-ce que le chômage frictionnel ?', 'mcq', '["Le chômage lié au temps de recherche et d’appariement","Le chômage dû à une récession","Le chômage volontaire","Le chômage des jeunes"]'::jsonb, 0, 'Il est incompressible : il existe même en plein emploi.', 4),
    ('718e7de6-2679-5bbb-b0e6-198165d24580'::uuid, 'e27d6632-816a-565b-95af-d437eb4beb75'::uuid, 'Qu’appelle-t-on hystérésis du chômage ?', 'mcq', '["Un chômage conjoncturel prolongé qui devient structurel","Une baisse rapide du chômage","La saisonnalité de l’emploi","Le chômage partiel"]'::jsonb, 0, 'Compétences dégradées, réseau distendu, signal négatif envoyé aux employeurs.', 5),
    ('c6199e4b-953b-50f7-b69f-43d0373e3063'::uuid, 'e27d6632-816a-565b-95af-d437eb4beb75'::uuid, 'La théorie insiders/outsiders explique que les salariés en place négocient à leur seul avantage.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les candidats extérieurs ne participent pas à la négociation salariale.', 6),
    ('a92460ea-a837-5335-963e-ffe5c211693a'::uuid, 'e27d6632-816a-565b-95af-d437eb4beb75'::uuid, 'Une politique de relance de la demande résout un chômage d’inadéquation des qualifications.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est sans effet sur ce type de chômage, qui appelle de la formation.', 7),
    ('73210803-9460-57d4-b05d-254fdd8f8cc4'::uuid, 'e27d6632-816a-565b-95af-d437eb4beb75'::uuid, 'Le chômage structurel disparaît en haut de cycle économique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est justement ce qui le définit : il subsiste même en période favorable.', 8),
    ('46ee67ba-cbc3-562b-9180-d913c983de18'::uuid, 'b71c65d5-379a-588b-9e4e-67d9284e9bde'::uuid, 'Quelle politique vise le chômage conjoncturel ?', 'mcq', '["La relance budgétaire ou monétaire","La formation professionnelle","La flexibilisation du licenciement","Les allègements de cotisations"]'::jsonb, 0, 'Elle soutient la demande anticipée, donc l’embauche.', 1),
    ('a3e45cb5-071d-5101-b027-1859a5ab233d'::uuid, 'b71c65d5-379a-588b-9e4e-67d9284e9bde'::uuid, 'Pourquoi les allègements de cotisations ciblent-ils les bas salaires ?', 'mcq', '["L’élasticité de l’emploi au coût du travail y est la plus forte","Parce que ces salariés sont les plus nombreux","Parce que la loi l’impose","Pour augmenter le salaire net"]'::jsonb, 0, 'On rapproche le coût du travail de la productivité des moins qualifiés.', 2),
    ('fcf570cb-d550-59ed-8a74-5bf91f68e993'::uuid, 'b71c65d5-379a-588b-9e4e-67d9284e9bde'::uuid, 'Qu’est-ce qu’un effet d’aubaine ?', 'mcq', '["Une aide versée pour une embauche qui aurait eu lieu de toute façon","Un gain imprévu de productivité","Une hausse soudaine de la demande","Un emploi créé par hasard"]'::jsonb, 0, 'C’est la principale limite des dispositifs d’aide à l’embauche.', 3),
    ('b367caf3-5b20-5a35-98cb-467163a3daf0'::uuid, 'b71c65d5-379a-588b-9e4e-67d9284e9bde'::uuid, 'Qu’appelle-t-on trappe à bas salaires ?', 'mcq', '["Le renchérissement brutal du coût du travail quand le salaire dépasse le seuil des allègements","Un salaire inférieur au SMIC","Un emploi à temps partiel","Une zone d’emploi sinistrée"]'::jsonb, 0, 'Les allègements dégressifs découragent les augmentations.', 4),
    ('e5d2c541-0a3d-520a-b273-050e6c72926b'::uuid, 'b71c65d5-379a-588b-9e4e-67d9284e9bde'::uuid, 'Les politiques actives de l’emploi consistent à indemniser les chômeurs.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est la définition des politiques passives ; les actives agissent sur l’emploi lui-même.', 5),
    ('beefbaea-1bcb-50f5-a36e-8153d96943d8'::uuid, 'b71c65d5-379a-588b-9e4e-67d9284e9bde'::uuid, 'En quoi consiste la flexicurité danoise ?', 'mcq', '["Une flexibilité de l’emploi assortie d’une indemnisation et d’un accompagnement forts","Une interdiction des licenciements","Un salaire minimum élevé","Un temps de travail réduit"]'::jsonb, 0, 'La sécurité porte sur la personne, pas sur le poste.', 6),
    ('d0ed8ace-619e-5d2e-8f87-8f14675ad928'::uuid, 'b71c65d5-379a-588b-9e4e-67d9284e9bde'::uuid, 'Quelle politique s’attaque au chômage d’inadéquation ?', 'mcq', '["La formation","La relance budgétaire","La baisse des taux directeurs","La dévaluation"]'::jsonb, 0, 'Ses effets sont les plus durables, mais aussi les plus lents.', 7),
    ('b52840a1-bb30-5fd7-9ae7-174a42fb4b27'::uuid, 'b71c65d5-379a-588b-9e4e-67d9284e9bde'::uuid, 'Dans une économie ouverte, une relance budgétaire peut se traduire par des importations.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ces « fuites » réduisent l’effet multiplicateur de la relance.', 8),
    ('b4c90e81-e077-5cc4-984f-26d7e8c28340'::uuid, '58388382-821f-50fa-84bb-dbea2db704bf'::uuid, 'Qu’est-ce que la titrisation ?', 'mcq', '["La transformation de créances en titres revendus sur les marchés","L’émission d’actions par une entreprise","Le rachat de dette publique par la banque centrale","La cotation en bourse d’une société"]'::jsonb, 0, 'Elle disperse le risque sans le supprimer, et le rend illisible.', 1),
    ('5894563a-3bb2-5aea-9e02-2b9666627df5'::uuid, '58388382-821f-50fa-84bb-dbea2db704bf'::uuid, 'Qu’appelle-t-on déflation par la dette ?', 'mcq', '["La baisse des prix qui alourdit la valeur réelle des dettes","L’annulation des dettes publiques","Une inflation supérieure aux taux d’intérêt","La dévaluation d’une monnaie"]'::jsonb, 0, 'Mécanisme décrit par Irving Fisher à propos de la crise de 1929.', 2),
    ('1e703332-b008-5c19-a775-6804350e86d4'::uuid, '58388382-821f-50fa-84bb-dbea2db704bf'::uuid, 'Quel événement de septembre 2008 a fait basculer la défiance en panique ?', 'mcq', '["La faillite de Lehman Brothers","Le krach de Wall Street","La faillite de la Grèce","La chute de l’euro"]'::jsonb, 0, 'Les banques ont alors cessé de se prêter entre elles.', 3),
    ('8920995c-05bf-5b74-b664-08b3ecbda3e0'::uuid, '58388382-821f-50fa-84bb-dbea2db704bf'::uuid, 'Les crédits subprimes étaient consentis à des ménages très solvables.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils visaient au contraire des emprunteurs peu solvables, gagés sur la hausse de l’immobilier.', 4),
    ('27275ea6-3ccc-5e12-8e7d-2cfc4c9f4749'::uuid, '58388382-821f-50fa-84bb-dbea2db704bf'::uuid, 'Qu’est-ce qui a évité en 2008 une dépression comparable à celle de 1929 ?', 'mcq', '["L’intervention massive des banques centrales, des États et des stabilisateurs automatiques","La disparition des banques","L’absence de contagion internationale","La faiblesse du crédit"]'::jsonb, 0, 'Les stabilisateurs automatiques n’existaient pas en 1929.', 5),
    ('b2b16c07-5c75-5569-b10a-ba4c18d6fa55'::uuid, '58388382-821f-50fa-84bb-dbea2db704bf'::uuid, 'La crise de 2008 s’est prolongée en Europe par une crise des dettes souveraines.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le sauvetage des banques a transféré la dette privée vers les États.', 6),
    ('39cf7e59-6aa7-50ce-a6df-f734d27ddac4'::uuid, '58388382-821f-50fa-84bb-dbea2db704bf'::uuid, 'Quelle est la première phase du scénario type d’une crise financière ?', 'mcq', '["Une phase d’euphorie, alimentée par le crédit et la hausse des prix d’actifs","La panique","La contagion à l’économie réelle","La régulation"]'::jsonb, 0, 'Puis viennent le retournement, la panique et la contagion.', 7),
    ('0d0f53b8-8456-5ba4-aa85-3f01b5795713'::uuid, '58388382-821f-50fa-84bb-dbea2db704bf'::uuid, 'Quelle a été l’erreur de politique économique après 1929 ?', 'mcq', '["L’orthodoxie budgétaire et monétaire, qui a aggravé la contraction","Une relance trop massive","Une baisse des taux trop rapide","La nationalisation des banques"]'::jsonb, 0, 'Le tournant vient du New Deal et, en théorie, de Keynes.', 8),
    ('7f29d00c-34bc-5bde-9b6a-63713f3b7190'::uuid, 'adf7bd2d-5676-5e91-b924-4050dc2bb5bb'::uuid, 'Qu’est-ce qu’une bulle spéculative ?', 'mcq', '["Un écart durable entre le prix d’un actif et sa valeur fondamentale","Une hausse des prix à la consommation","Un excès d’épargne","Une baisse brutale des taux d’intérêt"]'::jsonb, 0, 'L’actif est acheté pour être revendu plus cher, non pour ce qu’il rapporte.', 1),
    ('19f34d4b-00b5-5557-b37b-276f97dab338'::uuid, 'adf7bd2d-5676-5e91-b924-4050dc2bb5bb'::uuid, 'Que décrit la métaphore keynésienne du concours de beauté ?', 'mcq', '["Sur un marché, on anticipe le choix des autres et non la valeur réelle","Les entreprises se concurrencent par la publicité","Les actifs les plus rentables attirent les investisseurs","La bourse récompense les meilleures entreprises"]'::jsonb, 0, 'L’anticipation porte sur l’opinion moyenne, pas sur les fondamentaux.', 2),
    ('6a1e3a94-36c3-54a7-b44f-6ca281673883'::uuid, 'adf7bd2d-5676-5e91-b924-4050dc2bb5bb'::uuid, 'Qu’est-ce que l’aléa moral, appliqué aux banques ?', 'mcq', '["Une banque qui se sait secourue prend davantage de risques","Une banque qui ment sur ses comptes","Un emprunteur qui ne rembourse pas","Une fraude d’un trader isolé"]'::jsonb, 0, 'C’est le problème du « too big to fail ».', 3),
    ('184bc1c0-3ae0-593c-b4e8-83714a705c32'::uuid, 'adf7bd2d-5676-5e91-b924-4050dc2bb5bb'::uuid, 'Un bank run peut faire tomber une banque solvable.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle est illiquide à court terme, ayant transformé des dépôts courts en crédits longs.', 4),
    ('f32a4866-4b0c-5104-af29-637f2efbc5f9'::uuid, 'adf7bd2d-5676-5e91-b924-4050dc2bb5bb'::uuid, 'Quel est l’effet du levier d’endettement ?', 'mcq', '["Il amplifie les gains comme les pertes","Il réduit le risque de l’investisseur","Il garantit un rendement fixe","Il supprime le risque de contrepartie"]'::jsonb, 0, 'Apporter 10 et emprunter 90, c’est être ruiné par une baisse de 10 %.', 5),
    ('88b969eb-a961-5cbf-9818-c12a29a17e9a'::uuid, 'adf7bd2d-5676-5e91-b924-4050dc2bb5bb'::uuid, 'Que dit le paradoxe de la tranquillité de Minsky ?', 'mcq', '["Plus la stabilité dure, plus les agents s’endettent et plus le système devient fragile","Les crises sont imprévisibles par nature","La régulation supprime les bulles","L’instabilité est toujours d’origine extérieure"]'::jsonb, 0, 'La stabilité engendre l’instabilité.', 6),
    ('9332a9bf-e6fc-590a-a72e-50c801d32d0c'::uuid, 'adf7bd2d-5676-5e91-b924-4050dc2bb5bb'::uuid, 'Qu’est-ce que la sélection adverse sur le marché du crédit ?', 'mcq', '["La hausse du taux décourage les bons emprunteurs et attire les mauvais","Les banques refusent les petits prêts","Les emprunteurs choisissent la banque la moins chère","Les prêteurs privilégient les entreprises cotées"]'::jsonb, 0, 'Elle découle de l’asymétrie d’information avant la signature du contrat.', 7),
    ('48f78ff3-5008-529e-8e6e-a8ae92e9b358'::uuid, 'adf7bd2d-5676-5e91-b924-4050dc2bb5bb'::uuid, 'Une bulle est facile à identifier avant qu’elle n’éclate.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est ce qui rend la régulation préventive si difficile.', 8),
    ('97f46564-fe21-5fe4-84b2-04fb6cd7e901'::uuid, 'bdda7bd8-9e2f-5beb-bf9e-95c04b8ed609'::uuid, 'Quel est l’objectif principal de la BCE ?', 'mcq', '["La stabilité des prix, soit 2 % d’inflation à moyen terme","Le plein emploi","La croissance du PIB","L’équilibre budgétaire des États"]'::jsonb, 0, 'La Fed, elle, poursuit un double mandat : prix stables et plein emploi.', 1),
    ('027c3f0c-6eb6-515e-aaec-fe90299a2bc0'::uuid, 'bdda7bd8-9e2f-5beb-bf9e-95c04b8ed609'::uuid, 'Quel est l’effet d’une baisse des taux directeurs ?', 'mcq', '["Un crédit moins cher, donc plus d’investissement et de consommation","Une baisse de l’inflation immédiate","Une hausse de l’épargne","Une réduction de la dette publique"]'::jsonb, 0, 'C’est l’instrument conventionnel principal de la politique monétaire.', 2),
    ('701e7f6c-dd0b-577e-b852-236270f393bf'::uuid, 'bdda7bd8-9e2f-5beb-bf9e-95c04b8ed609'::uuid, 'Qu’est-ce que l’assouplissement quantitatif ?', 'mcq', '["L’achat massif de titres par la banque centrale pour faire baisser les taux longs","Une baisse des réserves obligatoires","Une annulation de la dette publique","Un prêt direct aux ménages"]'::jsonb, 0, 'Instrument non conventionnel, employé quand les taux directeurs atteignent zéro.', 3),
    ('4ac75803-e94a-554a-b6b1-dd87990c3648'::uuid, 'bdda7bd8-9e2f-5beb-bf9e-95c04b8ed609'::uuid, 'Que signifie « prêteur en dernier ressort » ?', 'mcq', '["La banque centrale prête sans limite aux banques solvables en cas de panique","L’État garantit tous les prêts bancaires","Les banques se prêtent entre elles","Le FMI prête aux États en difficulté"]'::jsonb, 0, 'C’est ce qui casse la mécanique du retrait de panique.', 4),
    ('22e9ebea-61ac-514b-9f64-ba8cad301131'::uuid, 'bdda7bd8-9e2f-5beb-bf9e-95c04b8ed609'::uuid, 'Que sont les accords de Bâle ?', 'mcq', '["Des règles prudentielles imposant aux banques des ratios de fonds propres et de liquidité","Des accords commerciaux","Un traité sur les taux de change","Un accord climatique"]'::jsonb, 0, 'S’y ajoute un coussin contracyclique à constituer en haut de cycle.', 5),
    ('7391b2c8-1144-55ed-a2c4-61836f97e64b'::uuid, 'bdda7bd8-9e2f-5beb-bf9e-95c04b8ed609'::uuid, 'En Europe, les dépôts sont garantis jusqu’à 100 000 euros par déposant et par banque.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Cette garantie décourage les retraits de panique.', 6),
    ('cd0d18c7-4479-5e84-a521-87ff8bf02d9c'::uuid, 'bdda7bd8-9e2f-5beb-bf9e-95c04b8ed609'::uuid, 'Qu’est-ce que le shadow banking ?', 'mcq', '["Des activités de financement hors du secteur bancaire supervisé","Le blanchiment d’argent","Les crédits accordés aux États","Les prêts entre particuliers"]'::jsonb, 0, 'C’est une limite connue de la régulation prudentielle.', 7),
    ('351e1a17-0e97-5d7b-a2bf-6ca113dc52c6'::uuid, 'bdda7bd8-9e2f-5beb-bf9e-95c04b8ed609'::uuid, 'La politique monétaire peut résoudre un chômage structurel.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle agit sur la conjoncture, pas sur l’inadéquation des qualifications.', 8),
    ('6c6234e7-1ee1-5f05-819c-6799a2b8a69d'::uuid, 'bda80f11-9fee-5c2b-8563-5be799993f3b'::uuid, 'Quelles sont les « quatre libertés » du marché commun ?', 'mcq', '["Circulation des biens, services, capitaux et personnes","Liberté d’entreprendre, de commercer, d’exporter et d’importer","Liberté des prix, des salaires, du crédit et du change","Circulation des marchandises, des étudiants, des retraités et des salariés"]'::jsonb, 0, 'Le marché commun est le troisième degré de la typologie de Balassa.', 1),
    ('bf103af1-c6d7-5997-9c34-b8e31012df6b'::uuid, 'bda80f11-9fee-5c2b-8563-5be799993f3b'::uuid, 'Qu’ajoute une union douanière à une zone de libre-échange ?', 'mcq', '["Un tarif extérieur commun","Une monnaie unique","La libre circulation des personnes","Un budget commun"]'::jsonb, 0, 'La zone de libre-échange se limite à la suppression des droits de douane internes.', 2),
    ('264980c5-4110-57fe-915c-edfa7303cdc9'::uuid, 'bda80f11-9fee-5c2b-8563-5be799993f3b'::uuid, 'Quels instruments un État perd-il en entrant dans l’union monétaire ?', 'mcq', '["La politique monétaire et la dévaluation","La politique budgétaire et la fiscalité","La politique de l’emploi","La politique commerciale uniquement"]'::jsonb, 0, 'Il ne lui reste que la politique budgétaire, elle-même encadrée.', 3),
    ('e210aef5-e061-5714-bfd1-b26e9731056b'::uuid, 'bda80f11-9fee-5c2b-8563-5be799993f3b'::uuid, 'Que prévoit le pacte de stabilité et de croissance ?', 'mcq', '["Un déficit public sous 3 % du PIB et une dette sous 60 %","Un taux d’inflation de 2 %","Un salaire minimum européen","Un budget fédéral de 5 % du PIB"]'::jsonb, 0, 'Il encadre le seul instrument budgétaire restant aux États.', 4),
    ('7c6876af-c83d-558b-8f94-d170d0cdc4d6'::uuid, 'bda80f11-9fee-5c2b-8563-5be799993f3b'::uuid, 'Selon Mundell, quelles conditions rendent une union monétaire viable ?', 'mcq', '["Mobilité du travail, flexibilité des prix, budget commun et cycles synchronisés","Une inflation nulle","Des dettes publiques identiques","Une langue commune"]'::jsonb, 0, 'La zone euro ne les remplit qu’imparfaitement.', 5),
    ('e7a6dfc1-661d-58e7-8963-84a3e4fea8d0'::uuid, 'bda80f11-9fee-5c2b-8563-5be799993f3b'::uuid, 'Le budget de l’Union européenne représente environ 1 % du PIB de l’Union.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est très peu pour amortir des chocs asymétriques entre États membres.', 6),
    ('7f7a542b-eeed-5511-9e68-1b6953cc3a5b'::uuid, 'bda80f11-9fee-5c2b-8563-5be799993f3b'::uuid, 'Qu’a créé l’Union européenne en 2020 pour financer son plan de relance ?', 'mcq', '["Un emprunt commun de grande ampleur","Une taxe européenne sur le revenu","Une nouvelle monnaie","Un impôt sur les sociétés unifié"]'::jsonb, 0, 'Première mutualisation budgétaire d’envergure de l’histoire de l’Union.', 7),
    ('f7c84e2a-fc48-5b03-a323-6de874076ec9'::uuid, 'bda80f11-9fee-5c2b-8563-5be799993f3b'::uuid, 'La politique de la concurrence permet à la Commission d’interdire une fusion.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle peut aussi sanctionner un abus de position dominante ou une aide d’État illégale.', 8),
    ('dff81d3b-57f6-5a50-b91e-aba48f142516'::uuid, 'd2a8c4ee-3bba-5e45-8817-0c068e5f9bf8'::uuid, 'Qu’est-ce qu’un choc asymétrique ?', 'mcq', '["Un choc qui frappe certains pays de l’union et pas d’autres","Un choc d’offre mondial","Une crise financière","Une hausse générale des prix"]'::jsonb, 0, 'Sans dévaluation possible, le pays touché doit passer par une dévaluation interne.', 1),
    ('54e89159-e554-5541-81c8-720c8090df88'::uuid, 'd2a8c4ee-3bba-5e45-8817-0c068e5f9bf8'::uuid, 'Qu’appelle-t-on dévaluation interne ?', 'mcq', '["Une baisse des salaires et des prix pour restaurer la compétitivité","Une dévaluation de la monnaie nationale","Une baisse des taux directeurs","Une hausse des droits de douane"]'::jsonb, 0, 'Longue, douloureuse et récessive, c’est le seul substitut à la dévaluation.', 2),
    ('de7a3770-3bcf-5ad9-8640-a2005b1b456f'::uuid, 'd2a8c4ee-3bba-5e45-8817-0c068e5f9bf8'::uuid, 'Pourquoi reproche-t-on au pacte de stabilité d’être procyclique ?', 'mcq', '["Il impose de réduire le déficit quand l’économie ralentit","Il autorise des déficits illimités","Il ne concerne que les petits États","Il impose une relance en haut de cycle"]'::jsonb, 0, 'La contrainte agit donc au pire moment.', 3),
    ('495b4ea2-e906-5002-91e5-155d3f5121d8'::uuid, 'd2a8c4ee-3bba-5e45-8817-0c068e5f9bf8'::uuid, 'Le pacte de stabilité a été suspendu en 2020.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Face à la pandémie, puis réformé pour laisser plus de place à l’investissement.', 4),
    ('c83accec-02d1-5562-ab13-a9148ce12ff6'::uuid, 'd2a8c4ee-3bba-5e45-8817-0c068e5f9bf8'::uuid, 'Pourquoi la modération salariale d’un pays est-elle une politique non coopérative ?', 'mcq', '["Elle améliore sa compétitivité au détriment de ses voisins","Elle réduit son propre PIB","Elle augmente l’inflation dans toute la zone","Elle est interdite par les traités"]'::jsonb, 0, 'C’est un gain relatif, obtenu sur les partenaires de la même union.', 5),
    ('3b37f033-31a2-566c-86ba-113b29d06d9c'::uuid, 'd2a8c4ee-3bba-5e45-8817-0c068e5f9bf8'::uuid, 'Qu’est-ce que le semestre européen ?', 'mcq', '["L’examen annuel des budgets nationaux avant leur vote","Une période de six mois sans droits de douane","Le calendrier des réunions de la BCE","Un fonds d’aide aux régions pauvres"]'::jsonb, 0, 'C’est l’un des rares instruments de coordination budgétaire.', 6),
    ('02d7cb2e-7a00-52fb-be65-81c91bef12d2'::uuid, 'd2a8c4ee-3bba-5e45-8817-0c068e5f9bf8'::uuid, 'La concurrence fiscale entre États membres augmente les recettes de tous.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Chacun baisse son taux pour attirer les bases, et tous perdent des recettes.', 7),
    ('1e068ffc-9cc9-51cd-87c4-d13866d2ff91'::uuid, 'd2a8c4ee-3bba-5e45-8817-0c068e5f9bf8'::uuid, 'Un taux directeur unique convient à toutes les conjonctures nationales.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est trop élevé pour un pays en récession, trop bas pour un pays en surchauffe.', 8),
    ('9af2699b-4699-563d-b03e-61f7b2991a17'::uuid, 'ae68791a-28e7-51f4-a4c3-68b36676ff3a'::uuid, 'Combien de grands groupes compte la nomenclature des PCS de l’INSEE ?', 'mcq', '["Six","Quatre","Huit","Douze"]'::jsonb, 0, 'Agriculteurs, artisans-commerçants, cadres, professions intermédiaires, employés, ouvriers.', 1),
    ('86ae47cb-8262-52a4-8fb0-7fb3b27a3a03'::uuid, 'ae68791a-28e7-51f4-a4c3-68b36676ff3a'::uuid, 'Sur quels critères la nomenclature des PCS est-elle construite ?', 'mcq', '["Le statut, la qualification et le secteur d’activité","Le revenu, le patrimoine et le diplôme","L’âge, le sexe et le lieu de résidence","Le niveau de vie uniquement"]'::jsonb, 0, 'Le statut distingue notamment les indépendants des salariés.', 2),
    ('5c1af15e-371c-5b57-bba3-d2d0132963bd'::uuid, 'ae68791a-28e7-51f4-a4c3-68b36676ff3a'::uuid, 'Quelle est une limite reconnue de la nomenclature des PCS ?', 'mcq', '["Elle repose sur l’activité professionnelle, mal adaptée aux inactifs","Elle compte trop de groupes","Elle ne distingue pas les salariés des indépendants","Elle est propre à la France d’avant 1950"]'::jsonb, 0, 'Retraités, chômeurs et étudiants y sont mal situés.', 3),
    ('71446e18-0894-5101-96ef-43bf6eff872a'::uuid, 'ae68791a-28e7-51f4-a4c3-68b36676ff3a'::uuid, 'Qu’est-ce qu’un effet d’âge, distingué d’un effet de génération ?', 'mcq', '["L’effet de la position dans le cycle de vie, indépendamment de l’année de naissance","L’effet du vieillissement de la population","L’effet du départ à la retraite","Un effet propre aux jeunes actifs"]'::jsonb, 0, 'Comparer deux âges différents mélange les deux effets.', 4),
    ('0e4e30fe-57b0-5956-91e9-4bfd498529ed'::uuid, 'ae68791a-28e7-51f4-a4c3-68b36676ff3a'::uuid, 'Quels trois ordres Weber distingue-t-il ?', 'mcq', '["Économique, social et politique","Public, privé et associatif","Rural, urbain et périurbain","Primaire, secondaire et tertiaire"]'::jsonb, 0, 'Les classes, les groupes de statut et les partis.', 5),
    ('35636453-30c4-5faf-8801-8dd52969d9e4'::uuid, 'ae68791a-28e7-51f4-a4c3-68b36676ff3a'::uuid, 'Les inégalités sont cumulatives : un désavantage en appelle souvent d’autres.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Diplôme, emploi, revenu, logement, santé : la chaîne se referme sur elle-même.', 6),
    ('fdd45005-19fe-59ce-b8f3-ec419fc7c8c7'::uuid, 'ae68791a-28e7-51f4-a4c3-68b36676ff3a'::uuid, 'Une analyse en termes de strates ordonne les individus sur une échelle continue.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’analyse en termes de classes, elle, distingue des groupes en opposition.', 7),
    ('66c93d53-7589-5ac5-9baa-adad2e23f8a0'::uuid, 'ae68791a-28e7-51f4-a4c3-68b36676ff3a'::uuid, 'Le programme demande de désigner un facteur de structuration principal.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il demande au contraire une approche multidimensionnelle, croisant les facteurs.', 8),
    ('194da134-8f03-5030-bf83-3b40322cb115'::uuid, 'f90e68fb-7c60-59ae-b704-e715576d7825'::uuid, 'Quelle part des actifs français est aujourd’hui salariée ?', 'mcq', '["Environ neuf sur dix","Environ deux sur trois","La moitié","Un sur trois"]'::jsonb, 0, 'Contre environ deux sur trois en 1950 : c’est la salarisation.', 1),
    ('b8628237-a297-5249-a5aa-82a6b982b96b'::uuid, 'f90e68fb-7c60-59ae-b704-e715576d7825'::uuid, 'Qu’est-ce que la tertiarisation ?', 'mcq', '["Le déplacement de l’emploi vers les services","La hausse du nombre d’indépendants","L’allongement de la scolarité","La croissance du secteur public"]'::jsonb, 0, 'Les services représentent environ trois emplois sur quatre.', 2),
    ('543ab58b-5d1e-5c11-a5f3-1374dc168cd6'::uuid, 'f90e68fb-7c60-59ae-b704-e715576d7825'::uuid, 'Quelles causes expliquent la désindustrialisation française ?', 'mcq', '["Gains de productivité, externalisation de services et délocalisations","Les délocalisations uniquement","La baisse de la demande de biens industriels","La hausse du prix de l’énergie seule"]'::jsonb, 0, 'Attribuer le phénomène aux seules délocalisations est l’erreur la plus courante.', 3),
    ('df8742c3-d063-5ac3-a528-d6990d754bc6'::uuid, 'f90e68fb-7c60-59ae-b704-e715576d7825'::uuid, 'La part des cadres dans la population active a fortement augmenté depuis 1950.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'D’environ 3 % à près de 20 %, tandis que celle des ouvriers reculait.', 4),
    ('9c87c795-ead6-59bd-9489-3002e1554213'::uuid, 'f90e68fb-7c60-59ae-b704-e715576d7825'::uuid, 'Que désigne la thèse de la moyennisation ?', 'mcq', '["L’absorption des extrêmes par une vaste classe moyenne","La baisse du revenu moyen","La convergence des salaires européens","L’uniformisation des diplômes"]'::jsonb, 0, 'Défendue par Mendras dans les années 1970, elle est contestée depuis les années 1990.', 5),
    ('b5a13107-5590-5908-b967-43575847b607'::uuid, 'f90e68fb-7c60-59ae-b704-e715576d7825'::uuid, 'Qu’observe-t-on depuis les années 1990 en matière d’emploi ?', 'mcq', '["Une polarisation : croissance des emplois très qualifiés et peu qualifiés, recul des intermédiaires","Une convergence de toutes les qualifications","Une disparition des emplois de service","Un retour de l’emploi industriel"]'::jsonb, 0, 'Elle nourrit la contestation de la thèse de la moyennisation.', 6),
    ('f8f71d9f-cae0-5883-be36-1e32286d48c1'::uuid, 'f90e68fb-7c60-59ae-b704-e715576d7825'::uuid, 'Les inégalités de patrimoine sont plus faibles que les inégalités de revenu.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elles sont bien plus fortes, et se sont accrues depuis les années 1980.', 7),
    ('cfeb3d13-16e0-5e4b-9b0e-967af654034f'::uuid, 'f90e68fb-7c60-59ae-b704-e715576d7825'::uuid, 'La massification scolaire a rebattu les positions relatives entre groupes sociaux.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle a élevé le niveau de tous sans modifier sensiblement les rangs.', 8),
    ('cad6f382-809b-520c-a43e-e6e764c27ecd'::uuid, 'c0976254-746a-5ecc-adb5-51c29ecaf4fc'::uuid, 'Chez Marx, qu’est-ce qui définit la classe sociale ?', 'mcq', '["La place dans les rapports de production","Le niveau de revenu","Le prestige social","Le diplôme obtenu"]'::jsonb, 0, 'Possède-t-on les moyens de production, ou seulement sa force de travail ?', 1),
    ('9673b622-8365-55c8-846a-1995e3cbc7aa'::uuid, 'c0976254-746a-5ecc-adb5-51c29ecaf4fc'::uuid, 'Quelle est la différence entre classe en soi et classe pour soi ?', 'mcq', '["La classe pour soi a conscience d’elle-même et agit collectivement","La classe en soi est plus riche","La classe pour soi est définie par le prestige","Il n’y a aucune différence"]'::jsonb, 0, 'Le passage de l’une à l’autre est le produit d’un travail politique.', 2),
    ('ab02bdc9-83ad-5a32-b548-c1cf2a5c4d6d'::uuid, 'c0976254-746a-5ecc-adb5-51c29ecaf4fc'::uuid, 'Quels sont les trois capitaux de Bourdieu ?', 'mcq', '["Économique, culturel et social","Physique, humain et naturel","Financier, immobilier et mobilier","Public, privé et symbolique"]'::jsonb, 0, 'Leur volume ET leur structure définissent la position sociale.', 3),
    ('70b20fb5-51e6-507c-be8e-a9d1a1da8c82'::uuid, 'c0976254-746a-5ecc-adb5-51c29ecaf4fc'::uuid, 'Qu’est-ce que l’habitus chez Bourdieu ?', 'mcq', '["L’ensemble des dispositions incorporées par la socialisation","Le lieu de résidence","Le niveau de revenu du ménage","Le métier exercé"]'::jsonb, 0, 'Il explique que les membres d’une même classe partagent goûts et manières.', 4),
    ('ff5fbe35-42c8-56bb-a927-8327f8b6944e'::uuid, 'c0976254-746a-5ecc-adb5-51c29ecaf4fc'::uuid, 'Chez Weber, un groupe de statut se définit par…', 'mcq', '["Le prestige et le style de vie","La propriété des moyens de production","Le revenu annuel","L’appartenance à un parti"]'::jsonb, 0, 'Les trois ordres — économique, social, politique — ne se recouvrent pas.', 5),
    ('fe00bebf-6a58-58cc-906b-344c438b4652'::uuid, 'c0976254-746a-5ecc-adb5-51c29ecaf4fc'::uuid, 'Chez Weber, la stratification sociale est binaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est continue et multidimensionnelle, contrairement à l’opposition marxienne.', 6),
    ('964101fc-809d-555d-849c-4acedc170368'::uuid, 'c0976254-746a-5ecc-adb5-51c29ecaf4fc'::uuid, 'Quel argument nourrit la thèse de l’affaiblissement des classes sociales ?', 'mcq', '["L’individualisation des trajectoires et le brouillage des frontières","La hausse des inégalités de patrimoine","La persistance de l’homogamie","La corrélation entre PCS et espérance de vie"]'::jsonb, 0, 'Les trois autres propositions plaident au contraire pour leur maintien.', 7),
    ('366cc319-a675-5e01-a007-75814f491c44'::uuid, 'c0976254-746a-5ecc-adb5-51c29ecaf4fc'::uuid, 'L’homogamie sociale désigne le fait de se mettre en couple dans son propre milieu.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Sa persistance est un argument en faveur de la pertinence des classes sociales.', 8),
    ('3210815c-bdac-58f7-bec9-0da360188ba0'::uuid, 'faed763c-242c-5c5e-8de3-cc54edc345b2'::uuid, 'Quelle est la différence entre massification et démocratisation scolaires ?', 'mcq', '["La massification est quantitative, la démocratisation réduit les écarts entre milieux sociaux","Ce sont deux synonymes","La démocratisation concerne l’enseignement privé","La massification concerne le supérieur uniquement"]'::jsonb, 0, 'La France a connu la première sans vraiment connaître la seconde.', 1),
    ('cc47a9cd-303a-50de-aae5-c001ac6a9410'::uuid, 'faed763c-242c-5c5e-8de3-cc54edc345b2'::uuid, 'Qu’est-ce que la démocratisation ségrégative décrite par Merle ?', 'mcq', '["Tous progressent, mais les milieux favorisés occupent les filières les plus rentables","Une séparation des élèves par sexe","La création d’écoles privées","L’exclusion des élèves en difficulté"]'::jsonb, 0, 'Les hiérarchies se déplacent à l’intérieur du système au lieu de se résorber.', 2),
    ('9fa16b32-bcf3-5b10-b6a0-3c014d93d2ba'::uuid, 'faed763c-242c-5c5e-8de3-cc54edc345b2'::uuid, 'Quelle réforme a créé le collège unique ?', 'mcq', '["La réforme Haby de 1975","La réforme Berthoin de 1959","La loi de 1985 sur le bac professionnel","La loi Jospin de 1989"]'::jsonb, 0, 'Elle supprime les filières séparées dès l’entrée en sixième.', 3),
    ('654ba10f-f9c4-5d50-bada-7e898dc4646a'::uuid, 'faed763c-242c-5c5e-8de3-cc54edc345b2'::uuid, 'Qu’est-ce que l’inflation scolaire ?', 'mcq', '["La dévaluation du diplôme quand les diplômés croissent plus vite que les emplois qualifiés","La hausse du coût des études","L’allongement de la scolarité obligatoire","La hausse du nombre d’enseignants"]'::jsonb, 0, 'Le paradoxe d’Anderson en découle directement.', 4),
    ('96d99f7c-4375-544e-a97c-2353a3dd5d80'::uuid, 'faed763c-242c-5c5e-8de3-cc54edc345b2'::uuid, 'Que dit le paradoxe d’Anderson ?', 'mcq', '["Être plus diplômé que son père ne garantit plus une position sociale supérieure","Les diplômés gagnent toujours plus","Le diplôme ne sert à rien","Les enfants de cadres réussissent mieux"]'::jsonb, 0, 'Le niveau de référence s’est élevé pour tout le monde.', 5),
    ('4744644c-5fa5-5bd6-a3c0-342f55df6bc5'::uuid, 'faed763c-242c-5c5e-8de3-cc54edc345b2'::uuid, 'Le diplôme ne protège plus du tout du chômage.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La dévaluation est relative : les non-diplômés restent bien plus exposés.', 6),
    ('86023f37-82ec-54fe-a63a-9a5abff9bfbc'::uuid, 'faed763c-242c-5c5e-8de3-cc54edc345b2'::uuid, 'Quelle part d’une génération obtient aujourd’hui le baccalauréat en France ?', 'mcq', '["Environ 80 %","Environ 50 %","Environ 95 %","Environ 30 %"]'::jsonb, 0, 'Contre environ 5 % en 1950.', 7),
    ('bd586bf8-28b8-5bb9-9ba1-1489d3f87467'::uuid, 'faed763c-242c-5c5e-8de3-cc54edc345b2'::uuid, 'Qu’appelle-t-on déclassement ?', 'mcq', '["Occuper un emploi en dessous de son niveau de diplôme","Perdre son emploi","Redoubler une classe","Changer de catégorie socioprofessionnelle"]'::jsonb, 0, 'C’est la manifestation individuelle de l’inflation scolaire.', 8),
    ('f32f361a-a849-502b-982b-8cce26f79d08'::uuid, 'df2afc58-82f4-5b4b-83fb-be625e2641b5'::uuid, 'Qu’est-ce que le capital culturel ?', 'mcq', '["Les savoirs, dispositions et références transmis par la famille et valorisés par l’École","Le budget culturel d’un ménage","Le nombre de livres publiés dans un pays","Les subventions à la culture"]'::jsonb, 0, 'Il existe sous forme incorporée, objectivée et institutionnalisée.', 1),
    ('6beaa89a-82c2-5d82-bdd8-7a4139c2d071'::uuid, 'df2afc58-82f4-5b4b-83fb-be625e2641b5'::uuid, 'Qu’appelle-t-on violence symbolique chez Bourdieu et Passeron ?', 'mcq', '["L’intériorisation par les dominés du verdict scolaire comme un jugement sur leurs capacités","Les violences physiques à l’école","La sanction disciplinaire","Le harcèlement scolaire"]'::jsonb, 0, 'Un héritage social y est perçu comme un don personnel.', 2),
    ('08cf7613-6c52-514d-a918-a15ae5e84af6'::uuid, 'df2afc58-82f4-5b4b-83fb-be625e2641b5'::uuid, 'Que met en avant l’explication de Boudon ?', 'mcq', '["Des choix d’orientation rationnels mais différents selon le milieu, à résultats égaux","La transmission du capital culturel","L’effet des enseignants","La carte scolaire"]'::jsonb, 0, 'Coûts, risques et bénéfices attendus ne sont pas les mêmes selon le milieu.', 3),
    ('74923fbb-32bf-5860-a501-e55f83eef2a6'::uuid, 'df2afc58-82f4-5b4b-83fb-be625e2641b5'::uuid, 'Les explications de Bourdieu et de Boudon se contredisent.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’une explique l’inégalité des armes, l’autre celle des choix à armes égales.', 4),
    ('5f1dcd58-ec6e-56cb-9fd3-505ab19be2ea'::uuid, 'df2afc58-82f4-5b4b-83fb-be625e2641b5'::uuid, 'Qu’est-ce que l’effet Pygmalion ?', 'mcq', '["L’influence des attentes de l’enseignant sur les résultats de l’élève","L’effet du redoublement","L’effet de la taille des classes","L’effet du niveau de diplôme des parents"]'::jsonb, 0, 'Il fait partie des inégalités produites par l’institution elle-même.', 5),
    ('ba527504-cd91-58bb-9a82-85c8db486931'::uuid, 'df2afc58-82f4-5b4b-83fb-be625e2641b5'::uuid, 'Environ quelle part des enfants de cadres obtient un diplôme du supérieur ?', 'mcq', '["Environ 70 %","Environ 30 %","Environ 50 %","Environ 95 %"]'::jsonb, 0, 'Contre moins de 30 % des enfants d’ouvriers.', 6),
    ('ed27643c-e4f3-574a-8b02-522f8d08224e'::uuid, 'df2afc58-82f4-5b4b-83fb-be625e2641b5'::uuid, 'Quelle politique vise directement les inégalités scolaires territoriales ?', 'mcq', '["L’éducation prioritaire (REP et REP+)","Le baccalauréat professionnel","Le collège unique","La semaine de quatre jours"]'::jsonb, 0, 'Créée en 1981 sous le nom de ZEP, elle a été renforcée par le dédoublement des CP.', 7),
    ('5c6c9746-ade6-55e0-962d-523d2f6411c2'::uuid, 'df2afc58-82f4-5b4b-83fb-be625e2641b5'::uuid, 'Les politiques d’éducation prioritaire ont totalement effacé les inégalités de réussite.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Leurs effets sont réels mais modestes : l’École ne compense pas seule.', 8),
    ('79bcdfc9-37d5-5588-a201-1370e186b3e6'::uuid, '890143ce-a512-5566-8026-a56344e262b7'::uuid, 'Comment se lit une table de destinée ?', 'mcq', '["En ligne : que deviennent les enfants d’un milieu donné","En colonne : d’où viennent les membres d’un groupe","En diagonale uniquement","Par totaux généraux"]'::jsonb, 0, 'La table de recrutement, elle, se lit en colonne.', 1),
    ('42e36103-bbe4-5880-ac1d-80f37f639059'::uuid, '890143ce-a512-5566-8026-a56344e262b7'::uuid, 'Qu’est-ce que la mobilité structurelle ?', 'mcq', '["La mobilité imposée par la transformation de la structure des emplois","La mobilité géographique","La mobilité au cours d’une carrière","La mobilité entre pays"]'::jsonb, 0, 'Quand les places de cadres augmentent, il faut bien que quelqu’un les occupe.', 2),
    ('f793070b-9501-547b-b078-7bedb88981f1'::uuid, '890143ce-a512-5566-8026-a56344e262b7'::uuid, 'Que mesure la fluidité sociale ?', 'mcq', '["La mobilité nette, une fois retiré l’effet des transformations de la structure des emplois","Le nombre total de personnes mobiles","La vitesse des changements de poste","La mobilité géographique interne"]'::jsonb, 0, 'Une société peut avoir beaucoup de mobilité observée et très peu de fluidité.', 3),
    ('c3c4243c-8abb-5e7c-9f98-ddb512626346'::uuid, '890143ce-a512-5566-8026-a56344e262b7'::uuid, 'La mobilité intergénérationnelle compare la position d’un individu à celle de ses parents.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La mobilité intragénérationnelle porte, elle, sur la carrière d’une même personne.', 4),
    ('f9000f56-15ea-51e6-afb4-0e1d26011620'::uuid, '890143ce-a512-5566-8026-a56344e262b7'::uuid, 'Qu’est-ce que la mobilité horizontale ?', 'mcq', '["Un changement de groupe sans changement de niveau social","Une ascension sociale","Un déclassement","Un déménagement"]'::jsonb, 0, 'La mobilité verticale, ascendante ou descendante, change le niveau.', 5),
    ('200b4a19-7226-506c-af8f-1df5d6e4739f'::uuid, '890143ce-a512-5566-8026-a56344e262b7'::uuid, 'On peut justifier une phrase issue de la table de destinée avec la table de recrutement.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est l’erreur numéro un : les groupes n’ont pas la même taille.', 6),
    ('1849ac0d-b382-56ae-8687-566f40a10915'::uuid, '890143ce-a512-5566-8026-a56344e262b7'::uuid, 'Quelle limite historique majeure les tables de mobilité présentent-elles ?', 'mcq', '["Elles ont longtemps ignoré les femmes ou les ont classées d’après leur conjoint","Elles ne portent que sur les cadres","Elles ne couvrent que le secteur public","Elles sont publiées tous les vingt ans"]'::jsonb, 0, 'S’y ajoutent les limites de la nomenclature des PCS elle-même.', 7),
    ('63156d0b-0f13-54ab-8ff8-83a62bda6145'::uuid, '890143ce-a512-5566-8026-a56344e262b7'::uuid, 'L’absence de mobilité sociale porte le nom de…', 'mcq', '["Reproduction sociale","Mobilité nulle structurelle","Immobilisme statutaire","Stagnation sociale"]'::jsonb, 0, 'C’est le terme employé par le programme.', 8),
    ('60943c5f-13b8-5620-96e6-007434208ab4'::uuid, '9b773f94-2fff-52fe-b8cd-a8f35c1c5cea'::uuid, 'Quelle part des hommes actifs occupe une position différente de celle de leur père ?', 'mcq', '["Environ deux tiers","Environ un tiers","La quasi-totalité","Environ un dixième"]'::jsonb, 0, 'Mais une grande partie de cette mobilité est structurelle.', 1),
    ('66fe0871-8425-5c64-9c0d-102f32a513ac'::uuid, '9b773f94-2fff-52fe-b8cd-a8f35c1c5cea'::uuid, 'La fluidité sociale française a-t-elle beaucoup évolué depuis les années 1980 ?', 'mcq', '["Non, elle est restée à peu près stable","Oui, elle a fortement augmenté","Oui, elle a été divisée par deux","Elle n’est pas mesurable"]'::jsonb, 0, 'C’est la mobilité observée, non la fluidité, qui a été forte.', 2),
    ('df057f6a-399e-56ad-8735-eba4cd7994d3'::uuid, '9b773f94-2fff-52fe-b8cd-a8f35c1c5cea'::uuid, 'La mobilité sociale française est majoritairement…', 'mcq', '["De courte distance","De longue distance","Descendante","Horizontale"]'::jsonb, 0, 'On passe d’ouvrier à employé bien plus souvent que d’ouvrier à cadre.', 3),
    ('21e569d7-c819-5093-9981-8e60f0b968d0'::uuid, '9b773f94-2fff-52fe-b8cd-a8f35c1c5cea'::uuid, 'Quelles positions de la hiérarchie sociale sont les plus fermées ?', 'mcq', '["Les deux extrémités","Les positions intermédiaires","Les professions indépendantes","Les emplois publics"]'::jsonb, 0, 'Fils de cadres et fils d’ouvriers reproduisent plus souvent la position de leur père.', 4),
    ('208bf2e8-6cc1-5cde-a401-dce173523416'::uuid, '9b773f94-2fff-52fe-b8cd-a8f35c1c5cea'::uuid, 'Qu’observe-t-on pour les générations nées après 1960 ?', 'mcq', '["Une mobilité descendante plus fréquente que pour leurs aînées","Une mobilité ascendante record","Une disparition du déclassement","Une immobilité totale"]'::jsonb, 0, 'La structure des emplois n’offre plus la même expansion de places qualifiées.', 5),
    ('40742399-ec69-59f3-bd1c-b7be9f069dad'::uuid, '9b773f94-2fff-52fe-b8cd-a8f35c1c5cea'::uuid, 'L’homogamie tend à limiter la mobilité sociale du ménage.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Se mettre en couple dans son propre milieu renforce la position d’origine.', 6),
    ('a138b9d8-ab0c-59cc-bef0-dfa4255feda6'::uuid, '9b773f94-2fff-52fe-b8cd-a8f35c1c5cea'::uuid, 'Qu’est-ce que le plafond de verre ?', 'mcq', '["L’ensemble des obstacles invisibles limitant l’accès des femmes aux postes dirigeants","Un seuil de revenu au-delà duquel l’impôt augmente","La limite d’âge des cadres dirigeants","Le niveau maximal de diplôme accessible"]'::jsonb, 0, 'Il explique que la mobilité apparente des femmes ne se traduise pas au sommet.', 7),
    ('2e9cc57a-1726-509b-ba79-f32fc098c3cf'::uuid, '9b773f94-2fff-52fe-b8cd-a8f35c1c5cea'::uuid, 'Une société fluide est nécessairement une société égalitaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La fluidité mesure la circulation entre positions, pas l’écart entre elles.', 8),
    ('50370b8c-bea4-5296-9c3a-8194506a712e'::uuid, 'd27568ad-2911-5978-a01a-4c5067427eb2'::uuid, 'Quelle part de l’emploi français est en CDI ?', 'mcq', '["Environ trois sur quatre","Environ la moitié","Environ un sur cinq","La quasi-totalité"]'::jsonb, 0, 'La norme reste majoritaire en stock, minoritaire en flux d’embauches.', 1),
    ('cb150f93-8a78-5843-a6dc-7307392bf03f'::uuid, 'd27568ad-2911-5978-a01a-4c5067427eb2'::uuid, 'Quelle part des embauches se fait en CDD ?', 'mcq', '["Plus de 85 %","Environ la moitié","Environ 15 %","Moins de 5 %"]'::jsonb, 0, 'Le CDI est devenu une position à atteindre plutôt qu’un point de départ.', 2),
    ('da694b25-daba-5c65-b322-0d04fe3b2b55'::uuid, 'd27568ad-2911-5978-a01a-4c5067427eb2'::uuid, 'Qu’est-ce que la polarisation de l’emploi ?', 'mcq', '["La croissance des emplois très qualifiés et peu qualifiés, avec recul des intermédiaires","La concentration de l’emploi dans les métropoles","L’opposition entre secteur public et privé","La séparation entre CDI et CDD"]'::jsonb, 0, 'Les emplois intermédiaires sont les plus exposés à l’automatisation.', 3),
    ('3cd2ebc1-dba9-594f-a1a3-4acc8fb04bc2'::uuid, 'd27568ad-2911-5978-a01a-4c5067427eb2'::uuid, 'Quel est l’enjeu juridique du travail de plateforme ?', 'mcq', '["La dépendance économique d’un travailleur juridiquement indépendant","La durée du temps de travail","Le niveau de qualification requis","La localisation des entreprises"]'::jsonb, 0, 'Plusieurs décisions de justice ont requalifié ces relations en contrat de travail.', 4),
    ('0d703bf6-2932-5e9c-bfca-dacde900a70c'::uuid, 'd27568ad-2911-5978-a01a-4c5067427eb2'::uuid, 'Un travailleur pauvre est une personne sans emploi.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un actif occupé dont le ménage vit sous le seuil de pauvreté.', 5),
    ('0ec7f66f-a44b-5c5b-b1cb-7f0d319ade1c'::uuid, 'd27568ad-2911-5978-a01a-4c5067427eb2'::uuid, 'Que distingue la théorie de la segmentation du marché du travail ?', 'mcq', '["Un marché primaire stable et un marché secondaire instable, faiblement communicants","Le secteur public et le secteur privé","Les grandes et les petites entreprises","Les emplois industriels et de service"]'::jsonb, 0, 'Jeunes, femmes et peu diplômés sont surreprésentés dans le second.', 6),
    ('9472bdd2-dc3b-56c1-81ab-6db7d5f377dd'::uuid, 'd27568ad-2911-5978-a01a-4c5067427eb2'::uuid, 'Le statut d’auto-entrepreneur, créé en 2009, a fait remonter la part des indépendants.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Après un siècle de baisse continue liée à la salarisation.', 7),
    ('c06dbf82-f51a-5440-985b-adeb14b92b96'::uuid, 'd27568ad-2911-5978-a01a-4c5067427eb2'::uuid, 'La précarité se réduit-elle au type de contrat de travail ?', 'mcq', '["Non : elle combine instabilité, faible revenu, horaires imprévisibles et absence de perspectives","Oui, seul le CDD est précaire","Oui, seul le temps partiel est précaire","Non, elle ne dépend que du revenu"]'::jsonb, 0, 'Un CDI à temps partiel subi peut être plus précaire qu’un CDD qualifié.', 8),
    ('905c5f94-7839-56bd-a7e8-5d7e1ca00ac1'::uuid, '56f8f880-03f4-543c-b7aa-f28e9f02203f'::uuid, 'Qu’est-ce que la division verticale du travail chez Taylor ?', 'mcq', '["La séparation entre ceux qui conçoivent et ceux qui exécutent","La décomposition en tâches élémentaires","La hiérarchie des salaires","La séparation entre ateliers"]'::jsonb, 0, 'La division horizontale, elle, découpe le travail en tâches répétitives.', 1),
    ('8e05c3e6-0bf6-57eb-bab6-cfdf49529efe'::uuid, '56f8f880-03f4-543c-b7aa-f28e9f02203f'::uuid, 'Qu’a ajouté Ford au taylorisme ?', 'mcq', '["La chaîne de montage, la standardisation et un salaire élevé","Le juste-à-temps","La polyvalence des opérateurs","L’auto-contrôle qualité"]'::jsonb, 0, 'Le five dollars day visait à retenir la main-d’œuvre et à solvabiliser la demande.', 2),
    ('405fedc3-14d9-5bdd-9eb0-bb52e236c4ed'::uuid, '56f8f880-03f4-543c-b7aa-f28e9f02203f'::uuid, 'Sur quel principe repose le juste-à-temps ?', 'mcq', '["Produire à la commande, sans stock","Produire en grande série pour stocker","Contrôler la qualité en fin de chaîne","Spécialiser chaque poste"]'::jsonb, 0, 'Le système devient réactif, mais fragile en cas de rupture d’approvisionnement.', 3),
    ('f07527b9-dec7-5e91-aaa4-fff9947427d3'::uuid, '56f8f880-03f4-543c-b7aa-f28e9f02203f'::uuid, 'Le toyotisme réduit l’intensité du travail par rapport au taylorisme.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le travail est plus varié, mais le juste-à-temps supprime les temps morts.', 4),
    ('f0d6895d-d7c2-523c-a2ce-2c3f9653645e'::uuid, '56f8f880-03f4-543c-b7aa-f28e9f02203f'::uuid, 'Qu’est-ce que le kaizen ?', 'mcq', '["L’amélioration continue, nourrie par les suggestions des opérateurs","Le contrôle qualité en fin de chaîne","Le chronométrage des tâches","Le salaire au rendement"]'::jsonb, 0, 'Il fait partie des principes du toyotisme.', 5),
    ('cad956f5-da30-51b9-a2c4-18d2208b80bf'::uuid, '56f8f880-03f4-543c-b7aa-f28e9f02203f'::uuid, 'Que dit le modèle de Karasek sur la santé au travail ?', 'mcq', '["La souffrance naît d’une forte demande combinée à une faible latitude décisionnelle","Le stress vient uniquement du temps de travail","Les troubles physiques sont plus graves que les psychiques","L’autonomie augmente toujours le stress"]'::jsonb, 0, 'Il explique les risques psychosociaux du management par objectifs.', 6),
    ('2c139260-3410-5ca2-8405-e7b711df8e54'::uuid, '56f8f880-03f4-543c-b7aa-f28e9f02203f'::uuid, 'Le management par objectifs remplace la surveillance directe par l’évaluation des résultats.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’autonomie dans les moyens s’accompagne d’une contrainte accrue sur les fins.', 7),
    ('fe6f45ac-fea4-51b2-b4e3-7b3471ccd1cf'::uuid, '56f8f880-03f4-543c-b7aa-f28e9f02203f'::uuid, 'Le toyotisme a fait entièrement disparaître le taylorisme.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une même entreprise peut combiner les deux modèles selon les services.', 8),
    ('f31d724d-356d-54f3-b5fe-16bfe745de94'::uuid, 'de39fca5-e4d9-5052-9b4a-2a0274b24612'::uuid, 'Par quels canaux le travail intègre-t-il ?', 'mcq', '["Économique, social et symbolique","Économique uniquement","Familial et scolaire","Politique et juridique"]'::jsonb, 0, 'Un revenu, un collectif, et une identité reconnue.', 1),
    ('878cd39d-9d2f-5e02-8b5c-d2e26e050da6'::uuid, 'de39fca5-e4d9-5052-9b4a-2a0274b24612'::uuid, 'Qu’est-ce que la solidarité organique chez Durkheim ?', 'mcq', '["L’unité née de la complémentarité des fonctions dans une société différenciée","L’unité née de la ressemblance entre individus","La solidarité familiale","La redistribution par l’État"]'::jsonb, 0, 'La solidarité mécanique, elle, caractérise les sociétés traditionnelles.', 2),
    ('69b0315d-5eed-5867-b5d4-192cfcfb5b33'::uuid, 'de39fca5-e4d9-5052-9b4a-2a0274b24612'::uuid, 'Que désigne la désaffiliation chez Castel ?', 'mcq', '["La situation de ceux qui n’ont ni travail ni lien social","La perte de nationalité","Le départ à la retraite","La rupture d’un contrat de travail"]'::jsonb, 0, 'Entre intégration et désaffiliation, il place la zone de vulnérabilité.', 3),
    ('96ca69fc-038f-5bce-98db-ae27fe8b8aa1'::uuid, 'de39fca5-e4d9-5052-9b4a-2a0274b24612'::uuid, 'Chez Castel, la vulnérabilité est une zone intermédiaire entre intégration et désaffiliation.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Travail précaire et relations fragiles : le basculement y est progressif.', 4),
    ('967d2a57-f885-5d48-93a4-c9f5fb3787c6'::uuid, 'de39fca5-e4d9-5052-9b4a-2a0274b24612'::uuid, 'Qu’est-ce qui affaiblit le collectif de travail selon le programme ?', 'mcq', '["L’individualisation des objectifs, des primes et des évaluations","La hausse des salaires","La réduction du temps de travail","La syndicalisation"]'::jsonb, 0, 'S’y ajoutent le télétravail et l’externalisation, qui dispersent les équipes.', 5),
    ('2f368776-2e24-5345-acb2-0325cb9710fd'::uuid, 'de39fca5-e4d9-5052-9b4a-2a0274b24612'::uuid, 'Le travail a cessé d’être une source d’identité pour les Français.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’attachement au travail reste élevé, y compris chez les jeunes générations.', 6),
    ('2d204693-0bad-58ca-948d-4e9cc5befb31'::uuid, 'de39fca5-e4d9-5052-9b4a-2a0274b24612'::uuid, 'Pourquoi le chômage de longue durée est-il particulièrement désintégrateur ?', 'mcq', '["Il détruit à la fois le revenu, le collectif et l’identité","Il empêche de déménager","Il réduit les droits civiques","Il diminue le niveau de diplôme"]'::jsonb, 0, 'Schnapper a montré comment il désorganise le temps et l’identité.', 7),
    ('d7922154-b9b4-5166-95e1-9c6511155b38'::uuid, 'de39fca5-e4d9-5052-9b4a-2a0274b24612'::uuid, 'En France, la protection sociale est largement adossée à l’emploi.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est pourquoi la fragilisation de l’emploi fragilise aussi cette instance d’intégration.', 8),
    ('fa1f981d-df71-57e3-b32a-66a373602a48'::uuid, '761c6b6a-ae81-5ca9-93db-df0d3cdab07d'::uuid, 'Qu’est-ce que le paradoxe de l’action collective d’Olson ?', 'mcq', '["L’individu rationnel a intérêt à ne pas participer, puisqu’il bénéficiera du résultat","Les groupes nombreux sont plus efficaces","L’action collective échoue toujours","Le vote est irrationnel"]'::jsonb, 0, 'C’est le problème du passager clandestin.', 1),
    ('8c471534-8669-51d6-ade3-8e8f8558d114'::uuid, '761c6b6a-ae81-5ca9-93db-df0d3cdab07d'::uuid, 'Qu’est-ce qu’une incitation sélective ?', 'mcq', '["Un avantage réservé aux seuls participants à l’action collective","Une prime versée par l’État","Un avantage fiscal pour les associations","Une réduction du temps de travail"]'::jsonb, 0, 'Services syndicaux ou caisse de grève en sont des exemples.', 2),
    ('33192253-cb10-5fcd-9019-21b3917611f6'::uuid, '761c6b6a-ae81-5ca9-93db-df0d3cdab07d'::uuid, 'Que désignent les rétributions symboliques du militantisme ?', 'mcq', '["La sociabilité, la reconnaissance et l’estime de soi que procure l’engagement","Les indemnités versées aux élus","Les cotisations syndicales","Les subventions publiques aux partis"]'::jsonb, 0, 'Concept développé par Daniel Gaxie.', 3),
    ('5176f6be-233d-5c16-a141-068822bf7678'::uuid, '761c6b6a-ae81-5ca9-93db-df0d3cdab07d'::uuid, 'La France a l’un des taux de syndicalisation les plus élevés de l’OCDE.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est au contraire l’un des plus faibles, autour de 10 %.', 4),
    ('7c6f064d-f495-5de9-878e-266e1f53649c'::uuid, '761c6b6a-ae81-5ca9-93db-df0d3cdab07d'::uuid, 'Quel facteur augmente le plus nettement la probabilité de s’engager ?', 'mcq', '["Le niveau de diplôme","Le lieu de résidence","La taille du ménage","Le type de contrat de travail"]'::jsonb, 0, 'Il joue sous toutes les formes d’engagement, du vote à la manifestation.', 5),
    ('09d387b2-d385-5429-a101-3e214d2e185e'::uuid, '761c6b6a-ae81-5ca9-93db-df0d3cdab07d'::uuid, 'Ceux qui manifestent sont généralement ceux qui votent le moins.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les répertoires se cumulent : ils ne se remplacent pas.', 6),
    ('c83d91e0-89b4-57eb-ba3f-02c63d74f5f8'::uuid, '761c6b6a-ae81-5ca9-93db-df0d3cdab07d'::uuid, 'Qu’appelle-t-on militantisme « post-it » ?', 'mcq', '["Un engagement intense, court et renouvelable, centré sur une cause","Le militantisme sur les réseaux sociaux uniquement","L’adhésion à un parti politique","Le vote systématique à chaque scrutin"]'::jsonb, 0, 'Expression de Jacques Ion, qui décrit un engagement plus distancié.', 7),
    ('53e7022a-8b8a-558e-b2af-80419f71c3e1'::uuid, '761c6b6a-ae81-5ca9-93db-df0d3cdab07d'::uuid, 'La consommation engagée est une forme d’engagement politique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Boycott et achat responsable en sont les deux faces.', 8),
    ('0961b83a-88fe-542e-a0a7-5ab40971106c'::uuid, '034bb51a-ba12-5e7e-809c-785bd692f575'::uuid, 'Qu’est-ce qui caractérise les nouveaux mouvements sociaux ?', 'mcq', '["Des enjeux d’identité, de droits et de mode de vie plutôt que de répartition","Une organisation syndicale très hiérarchisée","Un adversaire unique, l’employeur","Un recours exclusif à la grève"]'::jsonb, 0, 'Féminisme, écologie, antiracisme et droits des minorités en relèvent.', 1),
    ('32cced00-c349-5d3b-ab89-b7732a166a49'::uuid, '034bb51a-ba12-5e7e-809c-785bd692f575'::uuid, 'Que désigne le post-matérialisme d’Inglehart ?', 'mcq', '["La montée des valeurs d’autonomie et d’expression une fois les besoins matériels assurés","Le refus de la consommation","La disparition des inégalités matérielles","La croissance du secteur tertiaire"]'::jsonb, 0, 'Il explique le déplacement des enjeux des mobilisations.', 2),
    ('5e530435-5fbf-50b7-92f9-31128d7854ba'::uuid, '034bb51a-ba12-5e7e-809c-785bd692f575'::uuid, 'L’audience des syndicats français se mesure principalement…', 'mcq', '["Aux élections professionnelles","Au nombre d’adhérents","Au nombre de grèves","Aux sondages d’opinion"]'::jsonb, 0, 'Leur capacité de négociation excède largement leur taux d’adhésion.', 3),
    ('a1849e3b-ad11-5878-8c7e-3432b1864efe'::uuid, '034bb51a-ba12-5e7e-809c-785bd692f575'::uuid, 'La distinction entre anciens et nouveaux mouvements sociaux est aujourd’hui contestée.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les mobilisations récentes mêlent souvent revendications matérielles et de reconnaissance.', 4),
    ('642a317f-71c9-5324-b1f7-de0583665791'::uuid, '034bb51a-ba12-5e7e-809c-785bd692f575'::uuid, 'Quel effet le numérique a-t-il sur la mobilisation ?', 'mcq', '["Il abaisse le coût du déclenchement mais fragilise la négociation","Il augmente le nombre d’adhérents syndicaux","Il rend la grève plus efficace","Il n’a aucun effet mesurable"]'::jsonb, 0, 'Sans porte-parole légitime, un mouvement peut être massif et sans interlocuteur.', 5),
    ('faaf90cf-f95d-5e4b-a438-cdc06c5ddf77'::uuid, '034bb51a-ba12-5e7e-809c-785bd692f575'::uuid, 'Le recours au juge est devenu un répertoire d’action collective à part entière.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le contentieux climatique en est l’exemple le plus visible.', 6),
    ('2470ea51-ed46-5b99-b48a-1eac1dbdd37b'::uuid, '034bb51a-ba12-5e7e-809c-785bd692f575'::uuid, 'Qu’est-ce que le clicktivisme ?', 'mcq', '["Un engagement numérique nombreux mais de faible intensité","Le piratage de sites gouvernementaux","Le vote électronique","La collecte de dons en ligne"]'::jsonb, 0, 'Il illustre la dispersion que permet l’abaissement du coût de l’engagement.', 7),
    ('4f25bf0f-950a-53a3-8140-e21315e25c73'::uuid, '034bb51a-ba12-5e7e-809c-785bd692f575'::uuid, 'Les conflits du travail ont totalement disparu en France.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils se sont individualisés et diversifiés : débrayages courts, recours prud’homaux.', 8),
    ('9fb6ed56-e867-5798-8d24-d050850943a9'::uuid, 'f2d37f99-f4c3-5a26-b9e6-05ca62d58216'::uuid, 'Quand une différence devient-elle une inégalité ?', 'mcq', '["Quand elle se traduit par un accès inégal à des ressources socialement valorisées","Quand elle est mesurable","Quand elle concerne le revenu","Quand elle est jugée injuste"]'::jsonb, 0, 'Toute différence n’est pas une inégalité, et toute inégalité n’est pas jugée injuste.', 1),
    ('0ff8985b-e50a-51cc-9fdd-a98f0b9a959f'::uuid, 'f2d37f99-f4c3-5a26-b9e6-05ca62d58216'::uuid, 'Les inégalités de patrimoine sont-elles plus ou moins concentrées que celles de revenu ?', 'mcq', '["Bien plus concentrées","Bien moins concentrées","Identiques","Elles ne sont pas mesurables"]'::jsonb, 0, 'Les 10 % les mieux dotés détiennent environ la moitié du patrimoine.', 2),
    ('6350b1dc-c03f-565d-b229-3610b414fffa'::uuid, 'f2d37f99-f4c3-5a26-b9e6-05ca62d58216'::uuid, 'À quoi correspond le seuil de pauvreté en France ?', 'mcq', '["60 % du niveau de vie médian","50 % du revenu moyen","Le montant du SMIC","Le montant du RSA"]'::jsonb, 0, 'Il repose sur la médiane, moins sensible aux valeurs extrêmes que la moyenne.', 3),
    ('bffbd40e-101b-56aa-91f1-9307f67104aa'::uuid, 'f2d37f99-f4c3-5a26-b9e6-05ca62d58216'::uuid, 'Quelle est la différence entre pauvreté absolue et relative ?', 'mcq', '["L’absolue vise un panier de biens vitaux, la relative une distance au niveau de vie habituel","L’absolue concerne les pays pauvres uniquement","La relative est mesurée en revenu brut","Il n’y a aucune différence"]'::jsonb, 0, 'L’Union européenne retient la pauvreté relative.', 4),
    ('2c250fc0-04b5-583e-b4b9-efd01a152849'::uuid, 'f2d37f99-f4c3-5a26-b9e6-05ca62d58216'::uuid, 'Que signifie le caractère cumulatif des inégalités ?', 'mcq', '["Un désavantage en entraîne d’autres et se transmet","Les inégalités s’additionnent au hasard","Elles se compensent mutuellement","Elles disparaissent avec le temps"]'::jsonb, 0, 'C’est ce cumul qui rend l’inégalité structurelle.', 5),
    ('a726b4fb-5058-5448-bc6d-545825fe3090'::uuid, 'f2d37f99-f4c3-5a26-b9e6-05ca62d58216'::uuid, 'L’écart d’espérance de vie à 35 ans entre cadres et ouvriers est d’environ…', 'mcq', '["Six ans chez les hommes","Un an","Quinze ans","Il est nul"]'::jsonb, 0, 'C’est l’une des inégalités sociales les plus documentées.', 6),
    ('92271965-b32c-55b9-9065-97b071bec85a'::uuid, 'f2d37f99-f4c3-5a26-b9e6-05ca62d58216'::uuid, 'Une société peut réduire la pauvreté et voir les inégalités augmenter.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Si le haut de la distribution progresse plus vite que le bas.', 7),
    ('6e3f51ba-02c9-5691-a670-b7ec5cbfdbe7'::uuid, 'f2d37f99-f4c3-5a26-b9e6-05ca62d58216'::uuid, 'Que désigne l’intersectionnalité ?', 'mcq', '["Le croisement de plusieurs dimensions d’inégalité sur une même personne","La comparaison entre pays","L’égalité entre secteurs d’activité","Le croisement de deux tables statistiques"]'::jsonb, 0, 'Genre, origine, territoire et handicap peuvent se cumuler.', 8),
    ('ae42b272-5113-5787-91da-01a8d88212a7'::uuid, '13b1fc4c-e8a8-5533-bf59-5f566faaff93'::uuid, 'Que représente le rapport interdécile D9/D1 ?', 'mcq', '["Le rapport entre deux seuils de niveau de vie, celui des 10 % les plus aisés et celui des 10 % les plus modestes","Le rapport entre les revenus moyens des riches et des pauvres","La part du revenu des 10 % les plus riches","Le nombre de personnes pauvres"]'::jsonb, 0, 'D9 et D1 sont des seuils, pas des revenus moyens : la confusion est très pénalisée.', 1),
    ('f52b0814-9470-575e-8998-a62c3e861de4'::uuid, '13b1fc4c-e8a8-5533-bf59-5f566faaff93'::uuid, 'Que vaut l’indice de Gini en situation d’égalité parfaite ?', 'mcq', '["0","1","0,5","100"]'::jsonb, 0, 'Il vaut 1 quand une seule personne détient l’intégralité du revenu.', 2),
    ('2e3dbdb5-b2a3-5ed4-93b5-23d6a1245a07'::uuid, '13b1fc4c-e8a8-5533-bf59-5f566faaff93'::uuid, 'Que représente la courbe de Lorenz ?', 'mcq', '["La part cumulée du revenu détenue par la part cumulée de la population","L’évolution du revenu dans le temps","La répartition par catégorie socioprofessionnelle","La relation entre revenu et diplôme"]'::jsonb, 0, 'L’égalité parfaite y correspond à la diagonale.', 3),
    ('1b0d3448-320c-57f3-a99c-9493b8b631f7'::uuid, '13b1fc4c-e8a8-5533-bf59-5f566faaff93'::uuid, 'Deux distributions différentes peuvent avoir le même indice de Gini.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est la limite d’un indicateur synthétique : il résume la distribution en un seul chiffre.', 4),
    ('387f020b-2deb-57c2-b459-6ae17cf45fdc'::uuid, '13b1fc4c-e8a8-5533-bf59-5f566faaff93'::uuid, 'Quelle mesure éclaire spécifiquement le haut de la distribution ?', 'mcq', '["La part de la masse totale détenue par les 1 % les plus riches","L’indice de Gini","Le rapport interdécile","Le seuil de pauvreté"]'::jsonb, 0, 'Popularisée par les travaux de Piketty et du World Inequality Lab.', 5),
    ('193c9fb5-9d7b-5e22-9885-07dcc3147fa4'::uuid, '13b1fc4c-e8a8-5533-bf59-5f566faaff93'::uuid, 'Quelle est la différence entre revenu primaire et revenu disponible ?', 'mcq', '["Le disponible tient compte des prélèvements et des prestations","Le primaire inclut les revenus du patrimoine seulement","Le disponible exclut les salaires","Il n’y a aucune différence"]'::jsonb, 0, 'Préciser le périmètre est indispensable pour interpréter un chiffre.', 6),
    ('6a1baece-8ad7-5e7c-a07c-f17f4671afc1'::uuid, '13b1fc4c-e8a8-5533-bf59-5f566faaff93'::uuid, 'En France, l’essentiel de l’effet redistributif vient de la progressivité de l’impôt.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il vient surtout des prestations, notamment familiales et de logement.', 7),
    ('5ea4af59-9e38-5268-a457-a6ed7ef25986'::uuid, '13b1fc4c-e8a8-5533-bf59-5f566faaff93'::uuid, 'L’indice de Gini renseigne sur la mobilité sociale d’un pays.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il décrit la distribution à un instant donné, pas la circulation entre positions.', 8),
    ('984d7d8e-a1af-547e-bb6e-4920bd2e2689'::uuid, '3acce5bf-f3da-5961-bdf9-ff62c1f3526b'::uuid, 'Que défend l’égalité des chances ?', 'mcq', '["Que chacun parte avec les mêmes possibilités, quelles que soient ses origines","Que chacun obtienne le même revenu","Que les mêmes règles s’appliquent à tous","Que l’État ne redistribue pas"]'::jsonb, 0, 'Les positions inégales sont alors jugées justes si la compétition l’était.', 1),
    ('3dcfa935-2c41-52fa-883d-92daa0c3134d'::uuid, '3acce5bf-f3da-5961-bdf9-ff62c1f3526b'::uuid, 'Quel est le principe de différence de Rawls ?', 'mcq', '["Les inégalités ne sont justes que si elles profitent aux plus défavorisés","Toute inégalité est injuste","Le bien-être total doit être maximisé","La propriété est inviolable"]'::jsonb, 0, 'Il est choisi sous le voile d’ignorance, qui masque sa future position sociale.', 2),
    ('94270dfd-a6d0-5e81-8589-3965be21ed67'::uuid, '3acce5bf-f3da-5961-bdf9-ff62c1f3526b'::uuid, 'Que privilégie l’approche par les capabilités de Sen ?', 'mcq', '["La liberté réelle de faire quelque chose de ses ressources","Le revenu monétaire","L’égalité stricte des situations","La maximisation du bien-être total"]'::jsonb, 0, 'Donner un vélo à qui ne sait pas en faire n’est pas donner la mobilité.', 3),
    ('4d4fdce9-355a-5759-b396-aca6e9455abb'::uuid, '3acce5bf-f3da-5961-bdf9-ff62c1f3526b'::uuid, 'Selon Nozick, une redistribution imposée est légitime si elle réduit les inégalités.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Pour le libertarisme, seule la légitimité du processus d’acquisition compte.', 4),
    ('88d00383-3dcb-5f15-a4b5-18af6a3bebff'::uuid, '3acce5bf-f3da-5961-bdf9-ff62c1f3526b'::uuid, 'Qu’est-ce que la redistribution en nature ?', 'mcq', '["L’accès gratuit ou subventionné aux services collectifs comme l’école et la santé","Le versement du RSA","La distribution de biens alimentaires","Les allocations familiales"]'::jsonb, 0, 'Elle réduit les inégalités de niveau de vie réel sans passer par le revenu.', 5),
    ('5f20b9b2-1c24-5125-b023-a334b8648d0c'::uuid, '3acce5bf-f3da-5961-bdf9-ff62c1f3526b'::uuid, 'Qu’appelle-t-on non-recours ?', 'mcq', '["Le fait que des ayants droit ne demandent pas les prestations auxquelles ils ont droit","Le refus d’un emploi proposé","L’absence de recours juridique","La suppression d’une prestation"]'::jsonb, 0, 'Il limite fortement l’efficacité redistributive du système.', 6),
    ('92582af5-d78a-5248-bfb5-7d3a744bc31d'::uuid, '3acce5bf-f3da-5961-bdf9-ff62c1f3526b'::uuid, 'L’égalité des chances peut supposer des traitements différenciés.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Éducation prioritaire ou quotas heurtent l’égalité stricte des droits : c’est la tension du chapitre.', 7),
    ('1b370077-227c-5c28-babc-e1614422d0dc'::uuid, '3acce5bf-f3da-5961-bdf9-ff62c1f3526b'::uuid, 'Que vise l’utilitarisme de Bentham ?', 'mcq', '["Maximiser le bien-être total de la société","Protéger les droits de propriété","Améliorer le sort des plus défavorisés","Garantir l’égalité des résultats"]'::jsonb, 0, 'Quitte à accepter des inégalités si le total y gagne.', 8),
    ('87af7980-0776-5cce-9cd3-d06036f53bfd'::uuid, 'd2f4114d-5c5d-50d8-9d0d-38a02f2c6083'::uuid, 'Pourquoi le climat est-il qualifié de bien commun ?', 'mcq', '["Nul ne peut en être exclu, et sa dégradation affecte tout le monde","Il appartient aux États","Il est géré par l’ONU","Il est gratuit à produire"]'::jsonb, 0, 'Non excluable, et rival dans sa dégradation.', 1),
    ('8be07103-bbc3-5e71-a184-b51848ea9408'::uuid, 'd2f4114d-5c5d-50d8-9d0d-38a02f2c6083'::uuid, 'Qu’est-ce que la tragédie des communs ?', 'mcq', '["La destruction d’une ressource commune par l’addition de comportements individuellement rationnels","Une catastrophe naturelle","La faillite d’une entreprise publique","Un conflit entre États"]'::jsonb, 0, 'Concept popularisé par Hardin, nuancé ensuite par Ostrom.', 2),
    ('32813508-6fda-562e-b790-e9f2ae475fc8'::uuid, 'd2f4114d-5c5d-50d8-9d0d-38a02f2c6083'::uuid, 'Qu’a montré Elinor Ostrom ?', 'mcq', '["Des communautés locales peuvent gérer durablement une ressource commune avec des règles et un suivi","La privatisation est la seule solution","L’État doit tout gérer","La tragédie des communs est inévitable"]'::jsonb, 0, 'Règles, sanctions graduées, suivi et résolution des conflits en sont les conditions.', 3),
    ('a4b7863f-d067-5dff-86ad-85a8d930c6f2'::uuid, 'd2f4114d-5c5d-50d8-9d0d-38a02f2c6083'::uuid, 'Quelle est la différence majeure entre le protocole de Kyoto et l’accord de Paris ?', 'mcq', '["Kyoto imposait des objectifs contraignants à quelques pays, Paris repose sur des engagements volontaires universels","Paris est contraignant, Kyoto ne l’était pas","Kyoto concernait tous les pays","Paris ne fixe aucun objectif"]'::jsonb, 0, 'La logique passe de la contrainte négociée à la transparence et à la pression par les pairs.', 4),
    ('8e3cc5e1-42b3-5aac-8fb0-b234958e1a11'::uuid, 'd2f4114d-5c5d-50d8-9d0d-38a02f2c6083'::uuid, 'Quel est le rôle du GIEC ?', 'mcq', '["Produire et synthétiser l’expertise scientifique, sans pouvoir de décision","Fixer les objectifs contraignants de réduction","Sanctionner les États pollueurs","Financer la transition des pays pauvres"]'::jsonb, 0, 'Les décisions relèvent des conférences des parties de la CCNUCC.', 5),
    ('52cc49ff-8c71-5033-a865-0987c44b57aa'::uuid, 'd2f4114d-5c5d-50d8-9d0d-38a02f2c6083'::uuid, 'Une taxe carbone uniforme pèse proportionnellement davantage sur les ménages modestes.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ils sont plus dépendants de la voiture et consacrent une part plus grande de leur revenu à l’énergie.', 6),
    ('3083fa3f-796a-5ea8-bd56-7f27f5607863'::uuid, 'd2f4114d-5c5d-50d8-9d0d-38a02f2c6083'::uuid, 'Que désigne le principe des « responsabilités communes mais différenciées » ?', 'mcq', '["Tous les pays sont concernés, mais les développés portent une responsabilité historique plus grande","Chaque pays fixe librement ses objectifs","Seuls les pays pollueurs agissent","Les entreprises sont responsables, pas les États"]'::jsonb, 0, 'Il fonde le financement climatique vers les pays en développement.', 7),
    ('b2746b9d-b4f9-52e1-b51a-70fd50d6480f'::uuid, 'd2f4114d-5c5d-50d8-9d0d-38a02f2c6083'::uuid, 'Une politique climatique efficace est nécessairement acceptée socialement.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une politique perçue comme injuste est politiquement intenable, quelle que soit son efficacité.', 8),
    ('38d30e6a-5c60-526a-895c-5f4f855c65ea'::uuid, 'dfc037f8-500c-5392-9c6d-2665c0f4eef6'::uuid, 'Quels sont les trois grands instruments des politiques climatiques au programme ?', 'mcq', '["La réglementation, la taxation et le marché de quotas d’émission","L’impôt, la subvention et l’emprunt","La norme, la sanction pénale et la propagande","La recherche, l’éducation et le commerce"]'::jsonb, 0, 'Les politiques réelles les combinent plutôt qu’elles ne les opposent.', 1),
    ('b87ca317-0489-5dbc-acf6-857ad754a57b'::uuid, 'dfc037f8-500c-5392-9c6d-2665c0f4eef6'::uuid, 'Qu’est-ce qu’une taxe pigouvienne ?', 'mcq', '["Une taxe qui internalise l’externalité négative en la faisant payer au pollueur","Un impôt sur les bénéfices des industriels","Une taxe sur les importations polluantes","Une taxe affectée à la recherche"]'::jsonb, 0, 'Elle doit en principe égaler le dommage marginal causé.', 2),
    ('995bbc6c-2121-5c27-a77c-0491f43bbe18'::uuid, 'dfc037f8-500c-5392-9c6d-2665c0f4eef6'::uuid, 'Que garantit un marché de quotas d’émission ?', 'mcq', '["La quantité totale d’émissions, fixée par le plafond","Le prix du carbone","La réduction des inégalités","Le niveau des recettes publiques"]'::jsonb, 0, 'Le prix, lui, s’ajuste — et peut être très volatil.', 3),
    ('653582b4-2c1f-5057-8ecc-e38031b969bc'::uuid, 'dfc037f8-500c-5392-9c6d-2665c0f4eef6'::uuid, 'Quelle est la différence de principe entre taxe et marché de quotas ?', 'mcq', '["La taxe fixe le prix, le marché fixe la quantité","La taxe fixe la quantité, le marché fixe le prix","Les deux fixent le prix","Les deux fixent la quantité"]'::jsonb, 0, 'En situation d’incertitude, ce choix n’est pas neutre.', 4),
    ('b073e5b5-0374-500b-85bc-e197b8c7d740'::uuid, 'dfc037f8-500c-5392-9c6d-2665c0f4eef6'::uuid, 'Quelle est la principale limite de la réglementation ?', 'mcq', '["Elle impose le même effort à tous, sans tenir compte du coût de réduction de chacun","Elle est trop lente à décider","Elle rapporte trop peu de recettes","Elle est toujours inefficace"]'::jsonb, 0, 'Elle n’incite pas non plus à faire mieux que la norme.', 5),
    ('f581976e-5681-5ff1-9f1a-8f3575d7e770'::uuid, 'dfc037f8-500c-5392-9c6d-2665c0f4eef6'::uuid, 'Le protocole de Montréal a permis la reconstitution de la couche d’ozone.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Signé en 1987, il reste l’exemple d’une réglementation internationale réussie.', 6),
    ('953773b3-ca84-5727-a7ef-6666ae27b80f'::uuid, 'dfc037f8-500c-5392-9c6d-2665c0f4eef6'::uuid, 'De quoi dépend l’efficacité d’une taxe carbone ?', 'mcq', '["De l’élasticité-prix de la demande, donc de l’existence d’alternatives","Du nombre de contribuables","Du taux d’inflation","De la croissance du PIB"]'::jsonb, 0, 'Sans alternative, la taxe pèse sans réduire les émissions.', 7),
    ('aef06421-5e52-5410-a14f-d5d583b605cd'::uuid, 'dfc037f8-500c-5392-9c6d-2665c0f4eef6'::uuid, 'Un marché carbone dont le plafond est fixé trop haut voit le prix du quota s’effondrer.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ce fut le cas en Europe avant la mise en place de la réserve de stabilité.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('ses');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('ses')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 253 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 253 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
